package lowrisc_rom_ctrl_pkg;

  typedef struct packed {
    lowrisc_prim_mubi_pkg::mubi4_t done;
    lowrisc_prim_mubi_pkg::mubi4_t good;
  } pwrmgr_data_t;

  parameter pwrmgr_data_t PWRMGR_DATA_DEFAULT = '{
    done: lowrisc_prim_mubi_pkg::MuBi4True,
    good: lowrisc_prim_mubi_pkg::MuBi4True
  };

  typedef struct packed {
    logic [255:0] data;
    logic         valid;
  } keymgr_data_t;

  // Tie-off default for a keymgr ROM-digest input
  parameter keymgr_data_t KEYMGR_DATA_DEFAULT = '{
    data:  '0,
    valid: 1'b0
  };

  //
  // Encoding generated with:
  // $ ./util/design/sparse-fsm-encode.py -d 3 -m 7 -n 6 -s 2 --language=sv
  //
  // Hamming distance histogram:
  //
  //  0: --
  //  1: --
  //  2: --
  //  3: |||||||||||||||||||| (57.14%)
  //  4: ||||||||||||||| (42.86%)
  //  5: --
  //  6: --
  //
  // Minimum Hamming distance: 3
  // Maximum Hamming distance: 4
  // Minimum Hamming weight: 1
  // Maximum Hamming weight: 4
  //
  // However, we glom on an extra 4 bits to hold a mubi4_t that encodes "state == Done". The idea is
  // that we can use them for the rom_select_bus_o signal without needing an intermediate 1-bit
