/**
 * Data integrity decoder for bus integrity scheme
 */

module lowrisc_tlul_data_integ_dec import lowrisc_tlul_pkg::*; (
  // TL-UL interface
  input        [DataMaxWidth+DataIntgWidth-1:0] data_intg_i,
  output logic                                  data_err_o
);

  logic [1:0] data_err;
  lowrisc_prim_secded_inv_39_32_dec u_data_chk (
    .data_i(data_intg_i),
    .data_o(),
    .syndrome_o(),
    .err_o(data_err)
  );

  assign data_err_o = |data_err;

endmodule : lowrisc_tlul_data_integ_dec
