    unused_sigs = ^part_digest;
    hw2reg = '0;
    hw2reg.vendor_test_digest = part_digest[VendorTestIdx];
    hw2reg.creator_sw_cfg_digest = part_digest[CreatorSwCfgIdx];
    hw2reg.owner_sw_cfg_digest = part_digest[OwnerSwCfgIdx];
    hw2reg.rot_creator_auth_digest = part_digest[RotCreatorAuthIdx];
    hw2reg.rot_firmware_auth_slot0_digest = part_digest[RotFirmwareAuthSlot0Idx];
    hw2reg.rot_firmware_auth_slot1_digest = part_digest[RotFirmwareAuthSlot1Idx];
    hw2reg.rot_firmware_auth_slot2_digest = part_digest[RotFirmwareAuthSlot2Idx];
    hw2reg.rot_firmware_auth_slot3_digest = part_digest[RotFirmwareAuthSlot3Idx];
    hw2reg.soc_firmware_auth_slot0_digest = part_digest[SocFirmwareAuthSlot0Idx];
    hw2reg.soc_firmware_auth_slot1_digest = part_digest[SocFirmwareAuthSlot1Idx];
    hw2reg.soc_firmware_auth_slot2_digest = part_digest[SocFirmwareAuthSlot2Idx];
    hw2reg.soc_firmware_auth_slot3_digest = part_digest[SocFirmwareAuthSlot3Idx];
    hw2reg.hw_cfg0_digest = part_digest[HwCfg0Idx];
    hw2reg.hw_cfg1_digest = part_digest[HwCfg1Idx];
    hw2reg.secret0_digest = part_digest[Secret0Idx];
    hw2reg.secret1_digest = part_digest[Secret1Idx];
    hw2reg.secret2_digest = part_digest[Secret2Idx];
    hw2reg.secret3_digest = part_digest[Secret3Idx];
    return hw2reg;
  endfunction : named_reg_assign

  function automatic part_access_t [NumPart-1:0] named_part_access_pre(
      otp_ctrl_core_reg2hw_t reg2hw);
    part_access_t [NumPart-1:0] part_access_pre;
    logic unused_sigs;
    unused_sigs = ^reg2hw;
    // Default (this will be overridden by partition-internal settings).
    part_access_pre = {{32'(2*NumPart)}{lowrisc_prim_mubi_pkg::MuBi8False}};
    // Note: these could be made a MuBi CSRs in the future.
    // The main thing that is missing right now is proper support for W0C.
    // VENDOR_TEST
    if (!reg2hw.vendor_test_read_lock) begin
      part_access_pre[VendorTestIdx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // CREATOR_SW_CFG
    if (!reg2hw.creator_sw_cfg_read_lock) begin
      part_access_pre[CreatorSwCfgIdx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // OWNER_SW_CFG
    if (!reg2hw.owner_sw_cfg_read_lock) begin
      part_access_pre[OwnerSwCfgIdx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // AUTH_SLOT_STATE
    if (!reg2hw.auth_slot_state_read_lock) begin
      part_access_pre[AuthSlotStateIdx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // ROT_CREATOR_AUTH
    if (!reg2hw.rot_creator_auth_read_lock) begin
      part_access_pre[RotCreatorAuthIdx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // ROT_FIRMWARE_AUTH_SLOT0
    if (!reg2hw.rot_firmware_auth_slot0_read_lock) begin
      part_access_pre[RotFirmwareAuthSlot0Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // ROT_FIRMWARE_AUTH_SLOT1
    if (!reg2hw.rot_firmware_auth_slot1_read_lock) begin
      part_access_pre[RotFirmwareAuthSlot1Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // ROT_FIRMWARE_AUTH_SLOT2
    if (!reg2hw.rot_firmware_auth_slot2_read_lock) begin
      part_access_pre[RotFirmwareAuthSlot2Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // ROT_FIRMWARE_AUTH_SLOT3
    if (!reg2hw.rot_firmware_auth_slot3_read_lock) begin
      part_access_pre[RotFirmwareAuthSlot3Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // SOC_FIRMWARE_AUTH_SLOT0
    if (!reg2hw.soc_firmware_auth_slot0_read_lock) begin
      part_access_pre[SocFirmwareAuthSlot0Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // SOC_FIRMWARE_AUTH_SLOT1
    if (!reg2hw.soc_firmware_auth_slot1_read_lock) begin
      part_access_pre[SocFirmwareAuthSlot1Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // SOC_FIRMWARE_AUTH_SLOT2
    if (!reg2hw.soc_firmware_auth_slot2_read_lock) begin
      part_access_pre[SocFirmwareAuthSlot2Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // SOC_FIRMWARE_AUTH_SLOT3
    if (!reg2hw.soc_firmware_auth_slot3_read_lock) begin
      part_access_pre[SocFirmwareAuthSlot3Idx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    // EXT_NVM
    if (!reg2hw.ext_nvm_read_lock) begin
      part_access_pre[ExtNvmIdx].read_lock = lowrisc_prim_mubi_pkg::MuBi8True;
    end
    return part_access_pre;
  endfunction : named_part_access_pre

  function automatic otp_broadcast_t named_broadcast_assign(
      logic [NumPart-1:0] part_init_done,
      logic [4975:0][7:0] part_buf_data);
    otp_broadcast_t otp_broadcast;
    logic valid, unused;
    unused = 1'b0;
    valid = 1'b1;
    // VENDOR_TEST
    unused ^= ^{part_init_done[VendorTestIdx],
                part_buf_data[VendorTestOffset +: VendorTestSize]};
    // CREATOR_SW_CFG
    unused ^= ^{part_init_done[CreatorSwCfgIdx],
                part_buf_data[CreatorSwCfgOffset +: CreatorSwCfgSize]};
    // OWNER_SW_CFG
    unused ^= ^{part_init_done[OwnerSwCfgIdx],
                part_buf_data[OwnerSwCfgOffset +: OwnerSwCfgSize]};
    // AUTH_SLOT_STATE
    unused ^= ^{part_init_done[AuthSlotStateIdx],
                part_buf_data[AuthSlotStateOffset +: AuthSlotStateSize]};
    // ROT_CREATOR_AUTH
    unused ^= ^{part_init_done[RotCreatorAuthIdx],
                part_buf_data[RotCreatorAuthOffset +: RotCreatorAuthSize]};
    // ROT_FIRMWARE_AUTH_SLOT0
    unused ^= ^{part_init_done[RotFirmwareAuthSlot0Idx],
                part_buf_data[RotFirmwareAuthSlot0Offset +: RotFirmwareAuthSlot0Size]};
    // ROT_FIRMWARE_AUTH_SLOT1
    unused ^= ^{part_init_done[RotFirmwareAuthSlot1Idx],
                part_buf_data[RotFirmwareAuthSlot1Offset +: RotFirmwareAuthSlot1Size]};
    // ROT_FIRMWARE_AUTH_SLOT2
    unused ^= ^{part_init_done[RotFirmwareAuthSlot2Idx],
                part_buf_data[RotFirmwareAuthSlot2Offset +: RotFirmwareAuthSlot2Size]};
    // ROT_FIRMWARE_AUTH_SLOT3
    unused ^= ^{part_init_done[RotFirmwareAuthSlot3Idx],
                part_buf_data[RotFirmwareAuthSlot3Offset +: RotFirmwareAuthSlot3Size]};
    // SOC_FIRMWARE_AUTH_SLOT0
    unused ^= ^{part_init_done[SocFirmwareAuthSlot0Idx],
                part_buf_data[SocFirmwareAuthSlot0Offset +: SocFirmwareAuthSlot0Size]};
    // SOC_FIRMWARE_AUTH_SLOT1
    unused ^= ^{part_init_done[SocFirmwareAuthSlot1Idx],
                part_buf_data[SocFirmwareAuthSlot1Offset +: SocFirmwareAuthSlot1Size]};
    // SOC_FIRMWARE_AUTH_SLOT2
    unused ^= ^{part_init_done[SocFirmwareAuthSlot2Idx],
                part_buf_data[SocFirmwareAuthSlot2Offset +: SocFirmwareAuthSlot2Size]};
    // SOC_FIRMWARE_AUTH_SLOT3
    unused ^= ^{part_init_done[SocFirmwareAuthSlot3Idx],
                part_buf_data[SocFirmwareAuthSlot3Offset +: SocFirmwareAuthSlot3Size]};
    // EXT_NVM
    unused ^= ^{part_init_done[ExtNvmIdx],
                part_buf_data[ExtNvmOffset +: ExtNvmSize]};
    // HW_CFG0
    valid &= part_init_done[HwCfg0Idx];
    otp_broadcast.hw_cfg0_data = otp_hw_cfg0_data_t'(part_buf_data[HwCfg0Offset +: HwCfg0Size]);
    // HW_CFG1
    valid &= part_init_done[HwCfg1Idx];
    otp_broadcast.hw_cfg1_data = otp_hw_cfg1_data_t'(part_buf_data[HwCfg1Offset +: HwCfg1Size]);
    // SECRET0
    unused ^= ^{part_init_done[Secret0Idx],
                part_buf_data[Secret0Offset +: Secret0Size]};
    // SECRET1
    unused ^= ^{part_init_done[Secret1Idx],
                part_buf_data[Secret1Offset +: Secret1Size]};
    // SECRET2
    unused ^= ^{part_init_done[Secret2Idx],
                part_buf_data[Secret2Offset +: Secret2Size]};
    // SECRET3
    unused ^= ^{part_init_done[Secret3Idx],
                part_buf_data[Secret3Offset +: Secret3Size]};
    // LIFE_CYCLE
    unused ^= ^{part_init_done[LifeCycleIdx],
                part_buf_data[LifeCycleOffset +: LifeCycleSize]};
    otp_broadcast.valid = lowrisc_lc_ctrl_pkg::lc_tx_bool_to_lc_tx(valid);
    return otp_broadcast;
  endfunction : named_broadcast_assign

  function automatic otp_keymgr_key_t named_keymgr_key_assign(
      logic [NumPart-1:0][ScrmblBlockWidth-1:0] part_digest,
      logic [4975:0][7:0] part_buf_data,
      logic [39807:0] part_inv_default,
      lowrisc_lc_ctrl_pkg::lc_tx_t lc_seed_hw_rd_en);
    otp_keymgr_key_t otp_keymgr_key;
    logic valid, unused;
    unused = 1'b0;
    // For now we use a fixed struct type here so that the
    // interface to the keymgr remains stable. The type contains
    // a superset of all options, so we have to initialize it to '0 here.
    otp_keymgr_key = '0;
    // VENDOR_TEST
    unused ^= ^{part_digest[VendorTestIdx],
                part_buf_data[VendorTestOffset +: VendorTestSize]};
    // CREATOR_SW_CFG
    unused ^= ^{part_digest[CreatorSwCfgIdx],
                part_buf_data[CreatorSwCfgOffset +: CreatorSwCfgSize]};
    // OWNER_SW_CFG
    unused ^= ^{part_digest[OwnerSwCfgIdx],
                part_buf_data[OwnerSwCfgOffset +: OwnerSwCfgSize]};
    // AUTH_SLOT_STATE
    unused ^= ^{part_digest[AuthSlotStateIdx],
                part_buf_data[AuthSlotStateOffset +: AuthSlotStateSize]};
    // ROT_CREATOR_AUTH
    unused ^= ^{part_digest[RotCreatorAuthIdx],
                part_buf_data[RotCreatorAuthOffset +: RotCreatorAuthSize]};
    // ROT_FIRMWARE_AUTH_SLOT0
    unused ^= ^{part_digest[RotFirmwareAuthSlot0Idx],
                part_buf_data[RotFirmwareAuthSlot0Offset +: RotFirmwareAuthSlot0Size]};
    // ROT_FIRMWARE_AUTH_SLOT1
    unused ^= ^{part_digest[RotFirmwareAuthSlot1Idx],
                part_buf_data[RotFirmwareAuthSlot1Offset +: RotFirmwareAuthSlot1Size]};
    // ROT_FIRMWARE_AUTH_SLOT2
    unused ^= ^{part_digest[RotFirmwareAuthSlot2Idx],
                part_buf_data[RotFirmwareAuthSlot2Offset +: RotFirmwareAuthSlot2Size]};
    // ROT_FIRMWARE_AUTH_SLOT3
    unused ^= ^{part_digest[RotFirmwareAuthSlot3Idx],
                part_buf_data[RotFirmwareAuthSlot3Offset +: RotFirmwareAuthSlot3Size]};
    // SOC_FIRMWARE_AUTH_SLOT0
    unused ^= ^{part_digest[SocFirmwareAuthSlot0Idx],
                part_buf_data[SocFirmwareAuthSlot0Offset +: SocFirmwareAuthSlot0Size]};
    // SOC_FIRMWARE_AUTH_SLOT1
    unused ^= ^{part_digest[SocFirmwareAuthSlot1Idx],
                part_buf_data[SocFirmwareAuthSlot1Offset +: SocFirmwareAuthSlot1Size]};
    // SOC_FIRMWARE_AUTH_SLOT2
    unused ^= ^{part_digest[SocFirmwareAuthSlot2Idx],
                part_buf_data[SocFirmwareAuthSlot2Offset +: SocFirmwareAuthSlot2Size]};
    // SOC_FIRMWARE_AUTH_SLOT3
    unused ^= ^{part_digest[SocFirmwareAuthSlot3Idx],
                part_buf_data[SocFirmwareAuthSlot3Offset +: SocFirmwareAuthSlot3Size]};
    // EXT_NVM
    unused ^= ^{part_digest[ExtNvmIdx],
                part_buf_data[ExtNvmOffset +: ExtNvmSize]};
    // HW_CFG0
    unused ^= ^{part_digest[HwCfg0Idx],
                part_buf_data[HwCfg0Offset +: HwCfg0Size]};
    // HW_CFG1
    unused ^= ^{part_digest[HwCfg1Idx],
                part_buf_data[HwCfg1Offset +: HwCfg1Size]};
    // SECRET0
    unused ^= ^{part_digest[Secret0Idx],
                part_buf_data[Secret0Offset +: Secret0Size]};
    // SECRET1
    unused ^= ^{part_digest[Secret1Idx],
                part_buf_data[Secret1Offset +: Secret1Size]};
    // SECRET2
    valid = (part_digest[Secret2Idx] != 0);
    unused ^= ^part_buf_data[RmaTokenOffset +: RmaTokenSize];
    otp_keymgr_key.creator_root_key_share0_valid = valid;
    if (lowrisc_lc_ctrl_pkg::lc_tx_test_true_strict(lc_seed_hw_rd_en)) begin
      otp_keymgr_key.creator_root_key_share0 =
          part_buf_data[CreatorRootKeyShare0Offset +: CreatorRootKeyShare0Size];
    end else begin
      otp_keymgr_key.creator_root_key_share0 =
          part_inv_default[CreatorRootKeyShare0Offset*8 +: CreatorRootKeyShare0Size*8];
    end
    otp_keymgr_key.creator_root_key_share1_valid = valid;
    if (lowrisc_lc_ctrl_pkg::lc_tx_test_true_strict(lc_seed_hw_rd_en)) begin
      otp_keymgr_key.creator_root_key_share1 =
          part_buf_data[CreatorRootKeyShare1Offset +: CreatorRootKeyShare1Size];
    end else begin
      otp_keymgr_key.creator_root_key_share1 =
          part_inv_default[CreatorRootKeyShare1Offset*8 +: CreatorRootKeyShare1Size*8];
    end
    otp_keymgr_key.creator_seed_valid = valid;
    if (lowrisc_lc_ctrl_pkg::lc_tx_test_true_strict(lc_seed_hw_rd_en)) begin
      otp_keymgr_key.creator_seed =
          part_buf_data[CreatorSeedOffset +: CreatorSeedSize];
    end else begin
      otp_keymgr_key.creator_seed =
          part_inv_default[CreatorSeedOffset*8 +: CreatorSeedSize*8];
    end
    unused ^= ^part_buf_data[Secret2ZerOffset +: Secret2ZerSize];
    // This is not used since we consume the
    // ungated digest values from the part_digest array.
    unused ^= ^part_buf_data[Secret2DigestOffset +: Secret2DigestSize];
    // SECRET3
    valid = (part_digest[Secret3Idx] != 0);
    otp_keymgr_key.owner_seed_valid = valid;
    if (lowrisc_lc_ctrl_pkg::lc_tx_test_true_strict(lc_seed_hw_rd_en)) begin
      otp_keymgr_key.owner_seed =
          part_buf_data[OwnerSeedOffset +: OwnerSeedSize];
    end else begin
      otp_keymgr_key.owner_seed =
          part_inv_default[OwnerSeedOffset*8 +: OwnerSeedSize*8];
    end
    unused ^= ^part_buf_data[Secret3ZerOffset +: Secret3ZerSize];
    // This is not used since we consume the
    // ungated digest values from the part_digest array.
    unused ^= ^part_buf_data[Secret3DigestOffset +: Secret3DigestSize];
    // LIFE_CYCLE
    unused ^= ^{part_digest[LifeCycleIdx],
                part_buf_data[LifeCycleOffset +: LifeCycleSize]};
    unused ^= valid;
    return otp_keymgr_key;
  endfunction : named_keymgr_key_assign

