// Register with asynchronous reset.


///////////////////////////
// Macro for Sparse FSMs //
///////////////////////////

// Simulation tools typically infer FSMs and report coverage for these separately. However, tools
// like Xcelium and VCS seem to have problems inferring FSMs if the state register is not coded in
// a behavioral always_ff block in the same hierarchy. To that end, this uses a modified variant
// with a second behavioral register definition for RTL simulations so that FSMs can be inferred.
// Note that in this variant, the __q output is disconnected from prim_sparse_fsm_flop and attached
// to the behavioral flop. An assertion is added to ensure equivalence between the
// prim_sparse_fsm_flop output and the behavioral flop output in that case.


 // PRIM_FLOP_MACROS_SV


 // PRIM_ASSERT_SV


module lowrisc_mbx_core_reg_top
  # (
    parameter bit          EnableRacl           = 1'b0,
    parameter bit          RaclErrorRsp         = 1'b1,
    parameter lowrisc_top_racl_pkg::racl_policy_sel_t RaclPolicySelVec[lowrisc_mbx_reg_pkg::NumRegsCore] =
      '{lowrisc_mbx_reg_pkg::NumRegsCore{0}}
  ) (
  input clk_i,
  input rst_ni,
  input  lowrisc_tlul_pkg::tl_h2d_t tl_i,
  output lowrisc_tlul_pkg::tl_d2h_t tl_o,
  // To HW
  output lowrisc_mbx_reg_pkg::mbx_core_reg2hw_t reg2hw, // Write
  input  lowrisc_mbx_reg_pkg::mbx_core_hw2reg_t hw2reg, // Read

  // RACL interface
  input  lowrisc_top_racl_pkg::racl_policy_vec_t racl_policies_i,
  output lowrisc_top_racl_pkg::racl_error_log_t  racl_error_o,

  // Integrity check errors
  output logic intg_err_o
);

  import lowrisc_mbx_reg_pkg::* ;

  localparam int AW = 7;
  localparam int DW = 32;
  localparam int DBW = DW/8;                    // Byte Width

  // register signals
  logic           reg_we;
  logic           reg_re;
  logic [AW-1:0]  reg_addr;
  logic [DW-1:0]  reg_wdata;
  logic [DBW-1:0] reg_be;
  logic [DW-1:0]  reg_rdata;
  logic           reg_error;

  logic          addrmiss, wr_err;

  logic [DW-1:0] reg_rdata_next;
  logic reg_busy;

  lowrisc_tlul_pkg::tl_h2d_t tl_reg_h2d;
  lowrisc_tlul_pkg::tl_d2h_t tl_reg_d2h;


  // incoming payload check
  logic intg_err;
  lowrisc_tlul_cmd_intg_chk u_chk (
    .tl_i(tl_i),
    .err_o(intg_err)
  );

  // also check for spurious write enables
  logic reg_we_err;
  logic [16:0] reg_we_check;
  lowrisc_prim_reg_we_check #(
    .OneHotWidth(17)
  ) u_prim_reg_we_check (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .oh_i  (reg_we_check),
    .en_i  (reg_we && !addrmiss),
    .err_o (reg_we_err)
  );

  logic err_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      err_q <= '0;
    end else if (intg_err || reg_we_err) begin
      err_q <= 1'b1;
    end
  end

  // integrity error output is permanent and should be used for alert generation
  // register errors are transactional
  assign intg_err_o = err_q | intg_err | reg_we_err;

  // outgoing integrity generation
  lowrisc_tlul_pkg::tl_d2h_t tl_o_pre;
  lowrisc_tlul_rsp_intg_gen #(
    .EnableRspIntgGen(1),
    .EnableDataIntgGen(1)
  ) u_rsp_intg_gen (
    .tl_i(tl_o_pre),
    .tl_o(tl_o)
  );

  assign tl_reg_h2d = tl_i;
  assign tl_o_pre   = tl_reg_d2h;

  lowrisc_tlul_adapter_reg #(
    .RegAw(AW),
    .RegDw(DW),
    .EnableDataIntgGen(0)
  ) u_reg_if (
    .clk_i  (clk_i),
    .rst_ni (rst_ni),

    .tl_i (tl_reg_h2d),
    .tl_o (tl_reg_d2h),

    .en_ifetch_i(lowrisc_prim_mubi_pkg::MuBi4False),
    .intg_error_o(),

    .we_o    (reg_we),
    .re_o    (reg_re),
    .addr_o  (reg_addr),
    .wdata_o (reg_wdata),
    .be_o    (reg_be),
    .busy_i  (reg_busy),
    .rdata_i (reg_rdata),
    // Translate RACL error to TLUL error if enabled
    .error_i (reg_error | (RaclErrorRsp & racl_error_o.valid))
  );

  // cdc oversampling signals

  assign reg_rdata = reg_rdata_next ;
  assign reg_error = addrmiss | wr_err | intg_err;

  // Define SW related signals
  // Format: <reg>_<field>_{wd|we|qs}
  //        or <reg>_{wd|we|qs} if field == 1 or 0
  logic intr_state_we;
  logic intr_state_mbx_ready_qs;
  logic intr_state_mbx_ready_wd;
  logic intr_state_mbx_abort_qs;
  logic intr_state_mbx_abort_wd;
  logic intr_state_mbx_error_qs;
  logic intr_state_mbx_error_wd;
  logic intr_enable_we;
  logic intr_enable_mbx_ready_qs;
  logic intr_enable_mbx_ready_wd;
  logic intr_enable_mbx_abort_qs;
  logic intr_enable_mbx_abort_wd;
  logic intr_enable_mbx_error_qs;
  logic intr_enable_mbx_error_wd;
  logic intr_test_we;
  logic intr_test_mbx_ready_wd;
  logic intr_test_mbx_abort_wd;
  logic intr_test_mbx_error_wd;
  logic alert_test_we;
  logic alert_test_fatal_fault_wd;
  logic alert_test_recov_fault_wd;
  logic control_re;
  logic control_we;
  logic control_abort_qs;
  logic control_abort_wd;
  logic control_error_qs;
  logic control_error_wd;
  logic control_sys_async_msg_wd;
  logic status_re;
  logic status_busy_qs;
  logic status_sys_intr_state_qs;
  logic status_sys_intr_enable_qs;
  logic status_sys_async_enable_qs;
  logic address_range_regwen_we;
  logic [3:0] address_range_regwen_qs;
  logic [3:0] address_range_regwen_wd;
  logic address_range_valid_we;
  logic address_range_valid_qs;
  logic address_range_valid_wd;
  logic inbound_base_address_we;
  logic [29:0] inbound_base_address_qs;
  logic [29:0] inbound_base_address_wd;
  logic inbound_limit_address_we;
  logic [29:0] inbound_limit_address_qs;
  logic [29:0] inbound_limit_address_wd;
  logic inbound_write_ptr_re;
  logic [29:0] inbound_write_ptr_qs;
  logic outbound_base_address_we;
  logic [29:0] outbound_base_address_qs;
  logic [29:0] outbound_base_address_wd;
  logic outbound_limit_address_we;
  logic [29:0] outbound_limit_address_qs;
  logic [29:0] outbound_limit_address_wd;
  logic outbound_read_ptr_re;
  logic [29:0] outbound_read_ptr_qs;
  logic outbound_object_size_we;
  logic [10:0] outbound_object_size_qs;
  logic [10:0] outbound_object_size_wd;
  logic doe_intr_msg_addr_re;
  logic [31:0] doe_intr_msg_addr_qs;
  logic doe_intr_msg_data_re;
  logic [31:0] doe_intr_msg_data_qs;

  // Register instances
  // R[intr_state]: V(False)
  //   F[mbx_ready]: 0:0
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessW1C),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_state_mbx_ready (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_state_we),
    .wd     (intr_state_mbx_ready_wd),

    // from internal hardware
    .de     (hw2reg.intr_state.mbx_ready.de),
    .d      (hw2reg.intr_state.mbx_ready.d),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_state.mbx_ready.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_state_mbx_ready_qs)
  );

  //   F[mbx_abort]: 1:1
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessW1C),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_state_mbx_abort (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_state_we),
    .wd     (intr_state_mbx_abort_wd),

    // from internal hardware
    .de     (hw2reg.intr_state.mbx_abort.de),
    .d      (hw2reg.intr_state.mbx_abort.d),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_state.mbx_abort.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_state_mbx_abort_qs)
  );

  //   F[mbx_error]: 2:2
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessW1C),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_state_mbx_error (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_state_we),
    .wd     (intr_state_mbx_error_wd),

    // from internal hardware
    .de     (hw2reg.intr_state.mbx_error.de),
    .d      (hw2reg.intr_state.mbx_error.d),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_state.mbx_error.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_state_mbx_error_qs)
  );


  // R[intr_enable]: V(False)
  //   F[mbx_ready]: 0:0
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_enable_mbx_ready (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_enable_we),
    .wd     (intr_enable_mbx_ready_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_enable.mbx_ready.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_enable_mbx_ready_qs)
  );

  //   F[mbx_abort]: 1:1
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_enable_mbx_abort (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_enable_we),
    .wd     (intr_enable_mbx_abort_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_enable.mbx_abort.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_enable_mbx_abort_qs)
  );

  //   F[mbx_error]: 2:2
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_enable_mbx_error (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_enable_we),
    .wd     (intr_enable_mbx_error_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_enable.mbx_error.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_enable_mbx_error_qs)
  );


  // R[intr_test]: V(True)
  logic intr_test_qe;
  logic [2:0] intr_test_flds_we;
  assign intr_test_qe = &intr_test_flds_we;
  //   F[mbx_ready]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_intr_test_mbx_ready (
    .re     (1'b0),
    .we     (intr_test_we),
    .wd     (intr_test_mbx_ready_wd),
    .d      ('0),
    .qre    (),
    .qe     (intr_test_flds_we[0]),
    .q      (reg2hw.intr_test.mbx_ready.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.intr_test.mbx_ready.qe = intr_test_qe;

  //   F[mbx_abort]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_intr_test_mbx_abort (
    .re     (1'b0),
    .we     (intr_test_we),
    .wd     (intr_test_mbx_abort_wd),
    .d      ('0),
    .qre    (),
    .qe     (intr_test_flds_we[1]),
    .q      (reg2hw.intr_test.mbx_abort.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.intr_test.mbx_abort.qe = intr_test_qe;

  //   F[mbx_error]: 2:2
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_intr_test_mbx_error (
    .re     (1'b0),
    .we     (intr_test_we),
    .wd     (intr_test_mbx_error_wd),
    .d      ('0),
    .qre    (),
    .qe     (intr_test_flds_we[2]),
    .q      (reg2hw.intr_test.mbx_error.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.intr_test.mbx_error.qe = intr_test_qe;


  // R[alert_test]: V(True)
  logic alert_test_qe;
  logic [1:0] alert_test_flds_we;
  assign alert_test_qe = &alert_test_flds_we;
  //   F[fatal_fault]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_alert_test_fatal_fault (
    .re     (1'b0),
    .we     (alert_test_we),
    .wd     (alert_test_fatal_fault_wd),
    .d      ('0),
    .qre    (),
    .qe     (alert_test_flds_we[0]),
    .q      (reg2hw.alert_test.fatal_fault.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.alert_test.fatal_fault.qe = alert_test_qe;

  //   F[recov_fault]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_alert_test_recov_fault (
    .re     (1'b0),
    .we     (alert_test_we),
    .wd     (alert_test_recov_fault_wd),
    .d      ('0),
    .qre    (),
    .qe     (alert_test_flds_we[1]),
    .q      (reg2hw.alert_test.recov_fault.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.alert_test.recov_fault.qe = alert_test_qe;


  // R[control]: V(True)
  logic control_qe;
  logic [2:0] control_flds_we;
  assign control_qe = &control_flds_we;
  //   F[abort]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_control_abort (
    .re     (control_re),
    .we     (control_we),
    .wd     (control_abort_wd),
    .d      (hw2reg.control.abort.d),
    .qre    (),
    .qe     (control_flds_we[0]),
    .q      (reg2hw.control.abort.q),
    .ds     (),
    .qs     (control_abort_qs)
  );
  assign reg2hw.control.abort.qe = control_qe;

  //   F[error]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_control_error (
    .re     (control_re),
    .we     (control_we),
    .wd     (control_error_wd),
    .d      (hw2reg.control.error.d),
    .qre    (),
    .qe     (control_flds_we[1]),
    .q      (reg2hw.control.error.q),
    .ds     (),
    .qs     (control_error_qs)
  );
  assign reg2hw.control.error.qe = control_qe;

  //   F[sys_async_msg]: 3:3
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_control_sys_async_msg (
    .re     (1'b0),
    .we     (control_we),
    .wd     (control_sys_async_msg_wd),
    .d      ('0),
    .qre    (),
    .qe     (control_flds_we[2]),
    .q      (reg2hw.control.sys_async_msg.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.control.sys_async_msg.qe = control_qe;


  // R[status]: V(True)
  //   F[busy]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_status_busy (
    .re     (status_re),
    .we     (1'b0),
    .wd     ('0),
    .d      (hw2reg.status.busy.d),
    .qre    (),
    .qe     (),
    .q      (),
    .ds     (),
    .qs     (status_busy_qs)
  );

  //   F[sys_intr_state]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_status_sys_intr_state (
