  // R[address_range_regwen]: V(False)
  lowrisc_prim_subreg #(
    .DW      (4),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessW0C),
    .RESVAL  (4'h6),
    .Mubi    (1'b1)
  ) u_address_range_regwen (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (address_range_regwen_we),
