  ) u_csr0_field4 (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (csr0_we),
    .wd     (csr0_field4_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.csr0.field4.q),
    .ds     (),

    // to register interface (read)
    .qs     (csr0_field4_qs)
  );


  // R[csr1]: V(False)
  //   F[field0]: 6:0
  lowrisc_prim_subreg #(
    .DW      (7),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
    .RESVAL  (7'h0),
    .Mubi    (1'b0)
  ) u_csr1_field0 (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (csr1_we),
    .wd     (csr1_field0_wd),

    // from internal hardware
