  // R[csr2]: V(False)
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_csr2 (
