module lowrisc_rv_dm_dbg_reg_top (
  input clk_i,
  input rst_ni,
  input  lowrisc_tlul_pkg::tl_h2d_t tl_i,
  output lowrisc_tlul_pkg::tl_d2h_t tl_o,

  // Output port for window
  output lowrisc_tlul_pkg::tl_h2d_t tl_win_o,
  input  lowrisc_tlul_pkg::tl_d2h_t tl_win_i,

  // To HW

  // Integrity check errors
  output logic intg_err_o
);

  import lowrisc_rv_dm_reg_pkg::* ;


  // Add an unloaded flop to make use of clock / reset
  // This is done to specifically address lint complaints of unused clocks/resets
  // Since the flop is unloaded it will be removed during synthesis
  logic unused_reg;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      unused_reg <= '0;
    end else begin
      unused_reg <= tl_i.a_valid;
    end
  end



  // Since there are no registers in this block, commands are routed through to windows which
  // can report their own integrity errors.
  assign intg_err_o = 1'b0;

  // outgoing integrity generation
  lowrisc_tlul_pkg::tl_d2h_t tl_o_pre;
  lowrisc_tlul_rsp_intg_gen #(
    .EnableRspIntgGen(1),
    .EnableDataIntgGen(0)
  ) u_rsp_intg_gen (
    .tl_i(tl_o_pre),
    .tl_o(tl_o)
  );

  assign tl_win_o = tl_i;
  assign tl_o_pre = tl_win_i;

  // Unused signal tieoff
