module lowrisc_rv_dm
  import lowrisc_rv_dm_reg_pkg::*;
#(
  parameter logic [NumAlerts-1:0]           AlertAsyncOn                      = {NumAlerts{1'b1}},
  // Number of cycles a differential skew is tolerated on the alert signal
  parameter int unsigned                    AlertSkewCycles                   = 1,
  parameter logic [31:0]                    IdcodeValue                       = 32'h 0000_0001,
  parameter bit                             UseDmiInterface                   = 1'b0,
  parameter bit                             SecVolatileRawUnlockEn            = 0,
  parameter logic [lowrisc_tlul_pkg::RsvdWidth-1:0] TlulHostUserRsvdBits              = 0,
  parameter bit                             EnableRacl                        = 1'b0,
  parameter bit                             RaclErrorRsp                      = EnableRacl,
  parameter lowrisc_top_racl_pkg::racl_policy_sel_t RaclPolicySelVecRegs[NumRegsRegs] = '{NumRegsRegs{0}}
) (
  input  logic                clk_i,       // clock
  input  logic                clk_lc_i,    // only declared here so that the topgen
                                           // tooling connects the correct clk/rst domains.
  input  logic                rst_ni,      // asynchronous reset active low, connect PoR
                                           // here, not the system reset
  input  logic                rst_lc_ni,  // asynchronous reset active low, connect the lc
                                           // reset here. this is only used for NDM reset tracking.
  input  logic [31:0]         next_dm_addr_i, // static word address of the next debug module.
  // SEC_CM: LC_HW_DEBUG_CLR.INTERSIG.MUBI
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_hw_debug_clr_i,
  // SEC_CM: LC_HW_DEBUG_EN.INTERSIG.MUBI
  // HW Debug lifecycle enable signal (live version from the life cycle controller)
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_hw_debug_en_i,
  // SEC_CM: LC_DFT_EN.INTERSIG.MUBI
  // HW DFT lifecycle enable signal (live version from the life cycle controller)
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_dft_en_i,
  // HW Debug lifecycle enable signal (latched version from pinmux, only used for JTAG/TAP gating)
  input  lowrisc_lc_ctrl_pkg::lc_tx_t pinmux_hw_debug_en_i,
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_check_byp_en_i,
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_escalate_en_i,
  // Lifecycle init done indicator used to clear NDM latch after LC re-initialization
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_init_done_i,
  input                       strap_en_i,
  input                       strap_en_override_i,
  // SEC_CM: OTP_DIS_RV_DM_LATE_DEBUG.INTERSIG.MUBI
  // Late debug enable disablement signal coming from the OTP HW_CFG1 partition.
  input  lowrisc_prim_mubi_pkg::mubi8_t otp_dis_rv_dm_late_debug_i,
  input  lowrisc_prim_mubi_pkg::mubi4_t scanmode_i,
  input                       scan_rst_ni,
  output logic                ndmreset_req_o,  // non-debug module reset
  output logic                dmactive_o,  // debug module is active
  output logic [NrHarts-1:0]  debug_req_o, // async debug request
  input  logic [NrHarts-1:0]  unavailable_i, // communicate whether the hart is unavailable
                                             // (e.g.: power down)

  // bus device for comportable CSR access
  input  lowrisc_tlul_pkg::tl_h2d_t  regs_tl_d_i,
  output lowrisc_tlul_pkg::tl_d2h_t  regs_tl_d_o,

  // bus device with debug memory, for an execution based technique
  input  lowrisc_tlul_pkg::tl_h2d_t  mem_tl_d_i,
  output lowrisc_tlul_pkg::tl_d2h_t  mem_tl_d_o,

  // bus host, for system bus accesses
  output lowrisc_tlul_pkg::tl_h2d_t  sba_tl_h_o,
  input  lowrisc_tlul_pkg::tl_d2h_t  sba_tl_h_i,

  // Alerts
  input  lowrisc_prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i,
  output lowrisc_prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o,

  // RACL interface
  input  lowrisc_top_racl_pkg::racl_policy_vec_t racl_policies_i,
  output lowrisc_top_racl_pkg::racl_error_log_t  racl_error_o,

  // JTAG TAP
  input  lowrisc_jtag_pkg::jtag_req_t jtag_i,
  output lowrisc_jtag_pkg::jtag_rsp_t jtag_o,
  // TL-UL-based DMI
  input  lowrisc_tlul_pkg::tl_h2d_t dbg_tl_d_i,
  output lowrisc_tlul_pkg::tl_d2h_t dbg_tl_d_o
);

  ///////////////////////////
  // Parameter Definitions //
  ///////////////////////////

  import lowrisc_prim_mubi_pkg::mubi4_test_true_strict;
  import lowrisc_prim_mubi_pkg::mubi8_test_true_strict;
  import lowrisc_prim_mubi_pkg::mubi32_test_true_strict;
  import lowrisc_lc_ctrl_pkg::lc_tx_test_true_strict;



  // static debug hartinfo
  localparam lowrisc_dm::hartinfo_t DebugHartInfo = '{
    zero1:      '0,
    nscratch:   2, // Debug module needs at least two scratch regs
    zero0:      0,
    dataaccess: 1'b1, // data registers are memory mapped in the debugger
    datasize:   lowrisc_dm::DataCount,
    dataaddr:   lowrisc_dm::DataAddr
  };

  lowrisc_dm::hartinfo_t [NrHarts-1:0]      hartinfo;
  for (genvar i = 0; i < NrHarts; i++) begin : gen_dm_hart_ctrl
    assign hartinfo[i] = DebugHartInfo;
  end

  // Currently only 32 bit busses are supported by our TL-UL IP
  localparam int BusWidth = 32;
  // all harts have contiguous IDs
  localparam logic [NrHarts-1:0] SelectableHarts = {NrHarts{1'b1}};

  ///////////////
  // CSR Nodes //
  ///////////////

  lowrisc_tlul_pkg::tl_h2d_t mem_tl_win_h2d;
  lowrisc_tlul_pkg::tl_d2h_t mem_tl_win_d2h;
  lowrisc_rv_dm_reg_pkg::rv_dm_regs_reg2hw_t regs_reg2hw;
  logic regs_intg_error, rom_intg_error, dmi_intg_error, dbg_intg_error;
  logic sba_gate_intg_error, rom_gate_intg_error;

  lowrisc_rv_dm_regs_reg_top #(
    .EnableRacl(EnableRacl),
    .RaclErrorRsp(RaclErrorRsp),
    .RaclPolicySelVec(RaclPolicySelVecRegs)
  ) u_reg_regs (
    .clk_i,
    .rst_ni,
    .tl_i      (regs_tl_d_i    ),
    .tl_o      (regs_tl_d_o    ),
    .reg2hw    (regs_reg2hw    ),
    .racl_policies_i,
    .racl_error_o,
    // SEC_CM: BUS.INTEGRITY
    .intg_err_o(regs_intg_error)
  );

  // We are not instantiating the generated rv_dm_mem_reg_top, since the registers are actually
  // implemented inside the vendored-in rv_dm module from the PULP project.
  assign mem_tl_win_h2d = mem_tl_d_i;
  assign mem_tl_d_o = mem_tl_win_d2h;

  // Alerts
  logic [NumAlerts-1:0] alert_test, alerts;

  assign alerts[0] = regs_intg_error | rom_intg_error | dmi_intg_error | dbg_intg_error |
                     sba_gate_intg_error | rom_gate_intg_error;

  assign alert_test = {
    regs_reg2hw.alert_test.q &
    regs_reg2hw.alert_test.qe
  };

  for (genvar i = 0; i < NumAlerts; i++) begin : gen_alert_tx
    lowrisc_prim_alert_sender #(
      .AsyncOn(AlertAsyncOn[i]),
      .SkewCycles(AlertSkewCycles),
      .IsFatal(1'b1)
    ) u_prim_alert_sender (
      .clk_i,
      .rst_ni,
      .alert_test_i  ( alert_test[i] ),
      .alert_req_i   ( alerts[0]     ),
      .alert_ack_o   (               ),
      .alert_state_o (               ),
      .alert_rx_i    ( alert_rx_i[i] ),
      .alert_tx_o    ( alert_tx_o[i] )
    );
  end

  // Decode multibit scanmode enable
  logic testmode;
  assign testmode = mubi4_test_true_strict(scanmode_i);

  ///////////////////////
  // Life Cycle Gating //
  ///////////////////////

  // Debug enable gating.
  localparam int LcEnDebugReqVal = 4 - 1;
  localparam int LcEnResetReqVal = LcEnDebugReqVal + NrHarts;
  // +1 to get number of bits and another +1 because LcEnLastPos is one more than LcEnResetReq.
  localparam int RvDmLcEnSize    = $clog2(LcEnResetReqVal + 2);
  typedef enum logic [RvDmLcEnSize-1:0] {
    LcEnFetch,
    LcEnRom,
    LcEnSba,
    // LcEnDebugReq[NrHarts], <= this unfortunately does not work - SV-LRM mandates the use of
    // integral numbers. Parameters are not allowed in this context.
    LcEnDebugReq,
    // The above literal accommodates NrHarts number of debug requests - so we number the next
    // literal accordingly.
    LcEnResetReq = RvDmLcEnSize'(LcEnResetReqVal),
    // LcEnLastPos must immediately follow LcEnResetReq to calculate RvDmLcEnSize.
    LcEnLastPos
  } rv_dm_lc_en_e;
  // These must be equal so that the difference between LcEnResetReq and LcEnDebugReq is NrHarts.


  lowrisc_lc_ctrl_pkg::lc_tx_t lc_hw_debug_en;
  lowrisc_prim_lc_sync #(
    .NumCopies(1)
  ) u_prim_lc_sync_lc_hw_debug_en (
    .clk_i,
    .rst_ni,
    .lc_en_i(lc_hw_debug_en_i),
    .lc_en_o({lc_hw_debug_en})
  );

  lowrisc_lc_ctrl_pkg::lc_tx_t lc_dft_en;
  lowrisc_prim_lc_sync #(
    .NumCopies(1)
  ) u_prim_lc_sync_lc_dft_en (
    .clk_i,
    .rst_ni,
    .lc_en_i(lc_dft_en_i),
    .lc_en_o({lc_dft_en})
  );

  lowrisc_prim_mubi_pkg::mubi8_t [lowrisc_lc_ctrl_pkg::TxWidth-1:0] otp_dis_rv_dm_late_debug;
  lowrisc_prim_mubi8_sync #(
    .NumCopies (lowrisc_lc_ctrl_pkg::TxWidth)
  ) u_prim_mubi8_sync_otp_dis_rv_dm_late_debug (
    .clk_i,
    .rst_ni,
    .mubi_i(otp_dis_rv_dm_late_debug_i),
    .mubi_o(otp_dis_rv_dm_late_debug)
  );

  lowrisc_prim_mubi_pkg::mubi32_t [lowrisc_lc_ctrl_pkg::TxWidth-1:0] late_debug_enable;
  lowrisc_prim_mubi32_sync #(
    .NumCopies (lowrisc_lc_ctrl_pkg::TxWidth),
    .AsyncOn(0) // No synchronization required since the input signal is already synchronous.
  ) u_prim_mubi32_sync_late_debug_enable (
    .clk_i,
    .rst_ni,
    .mubi_i(lowrisc_prim_mubi_pkg::mubi32_t'(regs_reg2hw.late_debug_enable)),
    .mubi_o(late_debug_enable)
  );

  // SEC_CM: DM_EN.CTRL.LC_GATED
  // This implements a hardened MuBi multiplexor circuit where each output bitlane has its own
  // associated comparators for the enablement condition.
  logic [lowrisc_lc_ctrl_pkg::TxWidth-1:0] lc_hw_debug_en_raw;
  logic [lowrisc_lc_ctrl_pkg::TxWidth-1:0] lc_dft_en_raw;
  logic [lowrisc_lc_ctrl_pkg::TxWidth-1:0] lc_hw_debug_en_gated_raw;
  assign lc_hw_debug_en_raw = lc_hw_debug_en;
  assign lc_dft_en_raw = lc_dft_en;
  for (genvar k = 0; k < lowrisc_lc_ctrl_pkg::TxWidth; k++) begin : gen_mubi_mux
    assign lc_hw_debug_en_gated_raw[k] = (mubi8_test_true_strict(otp_dis_rv_dm_late_debug[k]) ||
                                          mubi32_test_true_strict(late_debug_enable[k])) ?
                                          lc_hw_debug_en_raw[k] :
                                          lc_dft_en_raw[k];
  end

  // The lc_hw_debug_en_gated signal modulates gating logic on the bus-side of the RV_DM.
  // The pinmux_hw_debug_en signal on the other hand modulates the TAP side of the RV_DM.
  // In order for the RV_DM to remain response during a NDM reset request, the TAP side
  // is not further modulated with the LATE_DEBUG_ENABLE CSR.
