      .data_i     (sram_rdata_scr),
      .data_o     (dec_data),
      .syndrome_o (),
      .err_o      (ecc_error)
    );

    logic [DataWidth-1:0] ecc_enc_data;
    lowrisc_prim_secded_inv_39_32_enc u_enc (
      .data_i(dec_data),
      .data_o(ecc_enc_data)
    );

