  logic reset_en_gated_we;
  assign reset_en_gated_we = reset_en_we & reset_en_regwen_qs;
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
