  ) u_wake_info_abort (
    .re     (wake_info_re),
    .we     (wake_info_we),
    .wd     (wake_info_abort_wd),
    .d      (hw2reg.wake_info.abort.d),
    .qre    (),
    .qe     (wake_info_flds_we[2]),
    .q      (reg2hw.wake_info.abort.q),
    .ds     (),
    .qs     (wake_info_abort_qs)
