    .clk_i   (clk_lc_i),
    .rst_ni  (rst_lc_ni),

    // from register interface
    .we     (1'b0),
    .wd     ('0),

    // from internal hardware
    .de     (hw2reg.fault_status.esc_timeout.de),
    .d      (hw2reg.fault_status.esc_timeout.d),

    // to internal hardware
    .qe     (),
