module lowrisc_rstmgr_leaf_rst
  import lowrisc_rstmgr_pkg::*;
  import lowrisc_rstmgr_reg_pkg::*;
  import lowrisc_prim_mubi_pkg::mubi4_t; #(
  parameter bit SecCheck = 1,
  parameter int SecMaxSyncDelay = 2,
  parameter bit SwRstReq = 1
) (
  input clk_i,
  input rst_ni,
  input leaf_clk_i,
  input parent_rst_ni,
  input sw_rst_req_ni,
  input lowrisc_prim_mubi_pkg::mubi4_t scanmode_i,
  input scan_rst_ni,
  output mubi4_t rst_en_o,
  output logic leaf_rst_o,
  output logic err_o,
  output logic fsm_err_o
);

  lowrisc_prim_mubi_pkg::mubi4_t scanmode;
  lowrisc_prim_mubi4_sync #(
    .NumCopies(1),
    .AsyncOn(0)
    ) u_scanmode_sync  (
    .clk_i,
    .rst_ni,
    .mubi_i(scanmode_i),
    .mubi_o({scanmode})
 );

  logic leaf_rst_sync;
  lowrisc_prim_flop_2sync #(
    .Width(1),
    .ResetValue('0)
  ) u_rst_sync (
    .clk_i(leaf_clk_i),
    .rst_ni(parent_rst_ni),
    .d_i(sw_rst_req_ni),
    .q_o(leaf_rst_sync)
  );

  lowrisc_prim_clock_mux2 #(
    .NoFpgaBufG(1'b1)
  ) u_rst_mux (
    .clk0_i(leaf_rst_sync),
    .clk1_i(scan_rst_ni),
    .sel_i(lowrisc_prim_mubi_pkg::mubi4_test_true_strict(scanmode)),
    .clk_o(leaf_rst_o)
  );

  logic sw_rst_req_q;
  logic clr_sw_rst_req;
  if (SwRstReq && SecCheck) begin : gen_sw_rst_req
    // once software requests a reset, hold on to the request until the consistency
    // checker passes the assertion check point
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
         sw_rst_req_q <= '0;
      end else if (sw_rst_req_q && clr_sw_rst_req) begin
         sw_rst_req_q <= '0;
      end else if (!sw_rst_req_q && !sw_rst_req_ni && !clr_sw_rst_req) begin
         sw_rst_req_q <= 1'b1;
      end
    end
  end else begin : gen_no_sw_rst_req
    //VCS coverage off
    // pragma coverage off
    logic unused_sig;
    assign unused_sig = clr_sw_rst_req;
    //VCS coverage on
    // pragma coverage on
    assign sw_rst_req_q = '0;
  end

  if (SecCheck) begin : gen_rst_chk

    // We have to create a separately synced reset for the child handshakes below, since keeping the
    // child side of the prim_sync_reqack synchronizer under reset would defeat the reset checker's
    // purpose, as it would never count any clock ticks in the WaitForChildRelease state above.
    logic leaf_chk_rst_n;
    lowrisc_prim_rst_sync u_prim_rst_sync (
      .clk_i      (leaf_clk_i),
      .d_i        (rst_ni),
      .q_o        (leaf_chk_rst_n),
      .scan_rst_ni,
      .scanmode_i
    );

    // SEC_CM: LEAF.RST.BKGN_CHK
    lowrisc_rstmgr_cnsty_chk #(
      .SecMaxSyncDelay(SecMaxSyncDelay),
      .SwRstReq(SwRstReq)
    ) u_rst_chk (
      .clk_i,
      .rst_ni,
      .child_clk_i(leaf_clk_i),
      .child_rst_ni(leaf_rst_o),
      .child_chk_rst_ni(leaf_chk_rst_n),
      .parent_rst_ni,
      .sw_rst_req_i(sw_rst_req_q | ~sw_rst_req_ni),
      .sw_rst_req_clr_o(clr_sw_rst_req),
      .err_o,
      .fsm_err_o
    );
  end else begin : gen_no_rst_chk
    logic unused_sig;
    assign unused_sig = sw_rst_req_q;
    assign clr_sw_rst_req = '0;
    assign err_o = '0;
    assign fsm_err_o = '0;
  end

  // reset asserted indication for alert handler
  lowrisc_prim_mubi4_sender #(
    .ResetValue(lowrisc_prim_mubi_pkg::MuBi4True)
  ) u_prim_mubi4_sender (
    .clk_i(leaf_clk_i),
    .rst_ni(leaf_rst_o),
    .mubi_i(lowrisc_prim_mubi_pkg::MuBi4False),
    .mubi_o(rst_en_o)
  );

endmodule // rstmgr_leaf_rst
