/**
 * Ibex RISC-V core
 *
 * 32 bit RISC-V core supporting the RV32I + optionally EMC instruction sets.
 * Instruction and data bus are 32 bit wide TileLink-UL (TL-UL).
 */
module lowrisc_rv_core_ibex
  import lowrisc_rv_core_ibex_pkg::*;
  import lowrisc_rv_core_ibex_reg_pkg::*;
#(
  parameter logic [NumAlerts-1:0]   AlertAsyncOn        = {NumAlerts{1'b1}},
  // Number of cycles a differential skew is tolerated on the alert and escalation signal
  parameter int unsigned            AlertSkewCycles     = 1,
  parameter bit                     PMPEnable           = 1'b1,
  parameter int unsigned            PMPGranularity      = 0,
  parameter int unsigned            PMPNumRegions       = 16,
  parameter int unsigned            MHPMCounterNum      = 10,
  parameter int unsigned            MHPMCounterWidth    = 32,
  parameter lowrisc_ibex_pkg::pmp_cfg_t     PMPRstCfg[16]       = lowrisc_ibex_pkg::PmpCfgRst,
  parameter logic [33:0]            PMPRstAddr[16]      = lowrisc_ibex_pkg::PmpAddrRst,
  parameter lowrisc_ibex_pkg::pmp_mseccfg_t PMPRstMsecCfg       = lowrisc_ibex_pkg::PmpMseccfgRst,
  parameter bit                     RV32E               = 0,
  parameter lowrisc_ibex_pkg::rv32m_e       RV32M               = lowrisc_ibex_pkg::RV32MSingleCycle,
  parameter lowrisc_ibex_pkg::rv32b_e       RV32B               = lowrisc_ibex_pkg::RV32BOTEarlGrey,
  parameter lowrisc_ibex_pkg::rv32zc_e      RV32ZC              = lowrisc_ibex_pkg::RV32ZcaZcbZcmp,
  parameter lowrisc_ibex_pkg::regfile_e     RegFile             = lowrisc_ibex_pkg::RegFileFF,
  parameter bit                     BranchTargetALU     = 1'b1,
  parameter bit                     WritebackStage      = 1'b1,
  parameter bit                     ICache              = 1'b1,
  parameter bit                     ICacheECC           = 1'b1,
  parameter bit                     ICacheScramble      = 1'b1,
  parameter int unsigned            ICacheNWays         = 2,
  parameter bit                     BranchPredictor     = 1'b0,
  parameter bit                     DbgTriggerEn        = 1'b1,
  parameter int unsigned            DbgHwBreakNum       = 4,
  parameter bit                     SecureIbex          = 1'b1,
  parameter int unsigned            LockstepOffset      = 1,
  parameter lowrisc_ibex_pkg::lfsr_seed_t   RndCnstLfsrSeed     = lowrisc_ibex_pkg::RndCnstLfsrSeedDefault,
  parameter lowrisc_ibex_pkg::lfsr_perm_t   RndCnstLfsrPerm     = lowrisc_ibex_pkg::RndCnstLfsrPermDefault,
  parameter int unsigned            DmBaseAddr          = 32'h1A110000,
  parameter int unsigned            DmAddrMask          = 32'h00000FFF,
  parameter int unsigned            DmHaltAddr          = 32'h1A110800,
  parameter int unsigned            DmExceptionAddr     = 32'h1A110808,
  parameter bit                     PipeLine            = 1'b0,
  parameter bit                     InstructionPipeline = 1'b0,
  parameter logic [lowrisc_ibex_pkg::SCRAMBLE_KEY_W-1:0] RndCnstIbexKeyDefault =
      lowrisc_ibex_pkg::RndCnstIbexKeyDefault,
  parameter logic [lowrisc_ibex_pkg::SCRAMBLE_NONCE_W-1:0] RndCnstIbexNonceDefault =
      lowrisc_ibex_pkg::RndCnstIbexNonceDefault,
  parameter int unsigned                    NEscalationSeverities = 4,
  parameter int unsigned                    WidthPingCounter      = 16,
  parameter logic [lowrisc_tlul_pkg::RsvdWidth-1:0] TlulHostUserRsvdBits   = 0,
  parameter logic [31:0]            CsrMvendorId                   = 32'b0,
  parameter logic [31:0]            CsrMimpId                      = 32'b0
) (
  // Clock and Reset
  input  logic        clk_i,
  input  logic        rst_ni,
  // Clock domain for edn
  input  logic        clk_edn_i,
  input  logic        rst_edn_ni,
  // Clock domain for escalation receiver
  input  logic        clk_esc_i,
  input  logic        rst_esc_ni,
  // Reset feedback to rstmgr
  output logic        rst_cpu_n_o,

  input  lowrisc_prim_ram_1p_pkg::ram_1p_cfg_req_t [ICacheNWays-1:0] ram_cfg_icache_tag_i,
  output lowrisc_prim_ram_1p_pkg::ram_1p_cfg_rsp_t [ICacheNWays-1:0] ram_cfg_icache_tag_o,
  input  lowrisc_prim_ram_1p_pkg::ram_1p_cfg_req_t [ICacheNWays-1:0] ram_cfg_icache_data_i,
  output lowrisc_prim_ram_1p_pkg::ram_1p_cfg_rsp_t [ICacheNWays-1:0] ram_cfg_icache_data_o,

  input  logic [31:0] hart_id_i,
  input  logic [31:0] boot_addr_i,

  // Instruction memory interface
  output lowrisc_tlul_pkg::tl_h2d_t     corei_tl_h_o,
  input  lowrisc_tlul_pkg::tl_d2h_t     corei_tl_h_i,

  // Data memory interface
  output lowrisc_tlul_pkg::tl_h2d_t     cored_tl_h_o,
  input  lowrisc_tlul_pkg::tl_d2h_t     cored_tl_h_i,

  // Interrupt inputs
  input  logic        irq_software_i,
  input  logic        irq_timer_i,
  input  logic        irq_external_i,

  // Escalation input for NMI
  input  lowrisc_prim_esc_pkg::esc_tx_t esc_tx_i,
  output lowrisc_prim_esc_pkg::esc_rx_t esc_rx_o,

  // watchdog NMI input
  input logic nmi_wdog_i,

  // Debug Interface
  input  logic        debug_req_i,

  // Crash dump information
  output cpu_crash_dump_t crash_dump_o,

  // CPU Control Signals
  input lowrisc_lc_ctrl_pkg::lc_tx_t lc_cpu_en_i,
  input lowrisc_lc_ctrl_pkg::lc_tx_t pwrmgr_cpu_en_i,
  output cpu_pwrmgr_t pwrmgr_o,

  // dft bypass
  input scan_rst_ni,
  input lowrisc_prim_mubi_pkg::mubi4_t scanmode_i,

  // peripheral interface access
  input  lowrisc_tlul_pkg::tl_h2d_t cfg_tl_d_i,
  output lowrisc_tlul_pkg::tl_d2h_t cfg_tl_d_o,

  // connection to edn
  output lowrisc_edn_pkg::edn_req_t edn_o,
  input lowrisc_edn_pkg::edn_rsp_t edn_i,

  // connection to otp scramble interface
  input clk_otp_i,
  input rst_otp_ni,
  output lowrisc_otp_ctrl_pkg::sram_otp_key_req_t icache_otp_key_o,
  input  lowrisc_otp_ctrl_pkg::sram_otp_key_rsp_t icache_otp_key_i,

  // fpga build info
  input [31:0] fpga_info_i,

  // interrupts and alerts
  input  lowrisc_prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i,
  output lowrisc_prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o

);

  import lowrisc_top_pkg::*;
  import lowrisc_tlul_pkg::*;

  // Register module
  rv_core_ibex_cfg_reg2hw_t reg2hw;
  rv_core_ibex_cfg_hw2reg_t hw2reg;

  // if pipeline=1, do not allow pass through and always break the path
  // if pipeline is 0, passthrough the fifo completely
  localparam bit FifoPass = PipeLine ? 1'b0 : 1'b1;
  localparam int unsigned FifoDepth = PipeLine ? 2 : 0;
  // ICache creates more outstanding transactions
  localparam int NumOutstandingReqs = ICache ? 8 : 2;

  // Main core instruction interface (internal)
  logic        main_core_instr_req, main_core_instr_req_q;
  logic        main_core_instr_gnt, main_core_instr_gnt_ibex;
  logic        main_core_instr_rvalid;
  logic [31:0] main_core_instr_addr, main_core_instr_addr_q;
  logic [31:0] main_core_instr_rdata;
  logic [6:0]  main_core_instr_rdata_intg;
  logic        main_core_instr_err;

  // Shadow core instruction interface (internal)
  logic        shadow_core_instr_req;
  logic [31:0] shadow_core_instr_addr;

  // Main core data interface (internal)
  logic        main_core_data_req;
  logic        main_core_data_gnt;
  logic        main_core_data_rvalid;
  logic        main_core_data_we;
  logic [3:0]  main_core_data_be;
  logic [31:0] main_core_data_addr;
  logic [31:0] main_core_data_wdata;
  logic [6:0]  main_core_data_wdata_intg;
  logic [31:0] main_core_data_rdata;
  logic [6:0]  main_core_data_rdata_intg;
  logic        main_core_data_err;

  // Shadow core data interface (internal)
  logic        shadow_core_data_req;
  logic        shadow_core_data_we;
  logic [3:0]  shadow_core_data_be;
  logic [31:0] shadow_core_data_addr;
  logic [31:0] shadow_core_data_wdata;
  logic [6:0]  shadow_core_data_wdata_intg;

  // Lockstep interface
  logic [3:0]  core_lockstep_cmp_en;

  // Pipeline interfaces
  tl_h2d_t tl_i_ibex2fifo;
  tl_d2h_t tl_i_fifo2ibex;
  tl_h2d_t tl_d_ibex2fifo_main_core;
  tl_d2h_t tl_d_fifo2ibex;

  // TLUL LC Gate interfaces
  tl_h2d_t tl_d_fifo2gate;
  tl_d2h_t tl_d_gate2fifo;

  logic tlul_lc_gate_core_d_error;



  import lowrisc_tlul_pkg::tl_h2d_t;
  import lowrisc_tlul_pkg::tl_d2h_t;
  localparam int TlH2DWidth = $bits(tl_h2d_t);
  localparam int TlD2HWidth = $bits(tl_d2h_t);

  // core sleeping
  logic core_sleep;

  // The following intermediate signals are created to aid in simulations.
  //
  // If a parent port is connected directly to a port of sub-modules, the implicit wire connection
  // can have only one procedural driver (assign, force etc). What that means is, it prevents us
  // from forcing the sub-module port without impacting the same port on other sub-modules. The
  // reason for this is, regardless of which hierarchy the port signal is forced, it is a singular
  // wire-connected entity - the effect of the force ends up getting reflected on the same port of
  // sub-modules, as well as the parent port. To achieve the behavior of a force on a sub-module
  // port not impacting (i.e. back-propagating to) the same port on parent / peer sub-modules, we
  // need to add an extra `logic` type variables between the port-port connections.
  logic ibex_top_clk_i;
  logic addr_trans_rst_ni;
  assign ibex_top_clk_i = clk_i;
  assign addr_trans_rst_ni = rst_ni;

  // errors and core alert events
  logic ibus_intg_err, dbus_intg_err;
  logic alert_minor, alert_major_internal, alert_major_bus;
  logic double_fault;
  logic fatal_intg_err, fatal_core_err, recov_core_err;
  logic alert_rv_d_tlul_comparison;
  logic alert_rv_i_tlul_comparison;

  // alert events to peripheral module
  logic fatal_intg_event;
  logic fatal_core_event;
  logic recov_core_event;
  // SEC_CM: BUS.INTEGRITY
  assign fatal_intg_event = ibus_intg_err | dbus_intg_err | alert_major_bus;
  assign fatal_core_event = alert_major_internal        |
                            double_fault                |
                            tlul_lc_gate_core_d_error   |
                            alert_rv_d_tlul_comparison  |
                            alert_rv_i_tlul_comparison;
  assign recov_core_event = alert_minor;

  // configurations for address translation
  region_cfg_t [NumRegions-1:0] ibus_region_cfg;
  region_cfg_t [NumRegions-1:0] dbus_region_cfg;

  // Reset feedback to clkmgr
  assign rst_cpu_n_o = rst_ni;

  // Escalation receiver that converts differential
  // protocol into single ended signal.
  logic esc_irq_nm;
  lowrisc_prim_esc_receiver #(
    .N_ESC_SEV   (NEscalationSeverities),
    .PING_CNT_DW (WidthPingCounter),
    .SkewCycles  (AlertSkewCycles)
  ) u_prim_esc_receiver (
    .clk_i     ( clk_esc_i  ),
    .rst_ni    ( rst_esc_ni ),
    .esc_req_o ( esc_irq_nm ),
    .esc_rx_o,
    .esc_tx_i
  );

  // Synchronize to fast Ibex clock domain.
  logic alert_irq_nm;
  lowrisc_prim_flop_2sync #(
    .Width(1)
  ) u_alert_nmi_sync (
    .clk_i,
    .rst_ni,
    .d_i(esc_irq_nm),
    .q_o(alert_irq_nm)
  );

  logic wdog_irq_nm;
  lowrisc_prim_flop_2sync #(
    .Width(1)
  ) u_wdog_nmi_sync (
    .clk_i,
    .rst_ni,
    .d_i(nmi_wdog_i),
    .q_o(wdog_irq_nm)
  );

  assign hw2reg.nmi_state.alert.d  = 1'b1;
  assign hw2reg.nmi_state.alert.de = alert_irq_nm;
  assign hw2reg.nmi_state.wdog.d   = 1'b1;
  assign hw2reg.nmi_state.wdog.de  = wdog_irq_nm;

  logic irq_nm;
  assign irq_nm = |(reg2hw.nmi_state & reg2hw.nmi_enable);

  lowrisc_lc_ctrl_pkg::lc_tx_t [1:0] lc_cpu_en;
  lowrisc_prim_lc_sync #(
    .NumCopies(2)
  ) u_lc_sync (
    .clk_i,
    .rst_ni,
    .lc_en_i(lc_cpu_en_i),
    .lc_en_o(lc_cpu_en)
  );

  lowrisc_lc_ctrl_pkg::lc_tx_t [0:0] pwrmgr_cpu_en;
  lowrisc_prim_lc_sync u_pwrmgr_sync (
    .clk_i,
    .rst_ni,
    .lc_en_i(pwrmgr_cpu_en_i),
    .lc_en_o(pwrmgr_cpu_en)
  );

  // timer interrupts do not come from
  // rv_plic and may not be synchronous to the ibex core
  logic irq_timer_sync;
  lowrisc_prim_flop_2sync #(
    .Width(1)
  ) u_intr_timer_sync (
    .clk_i,
    .rst_ni,
    .d_i(irq_timer_i),
    .q_o(irq_timer_sync)
  );


  logic irq_software;
  logic irq_timer;
  logic irq_external;

  lowrisc_prim_sec_anchor_buf #(
    .Width(3)
  ) u_prim_buf_irq (
    .in_i({irq_software_i,
           irq_timer_sync,
           irq_external_i}),
    .out_o({irq_software,
            irq_timer,
            irq_external})
  );


  logic key_req, key_ack;
  logic [lowrisc_ibex_pkg::SCRAMBLE_KEY_W-1:0] key;
  logic [lowrisc_ibex_pkg::SCRAMBLE_NONCE_W-1:0] nonce;
  logic unused_seed_valid;
  localparam int PayLoadW = lowrisc_ibex_pkg::SCRAMBLE_KEY_W + lowrisc_ibex_pkg::SCRAMBLE_NONCE_W + 1;
  lowrisc_prim_sync_reqack_data #(
    .Width(PayLoadW),
    .DataSrc2Dst(1'b0)
  ) u_prim_sync_reqack_data (
    .clk_src_i  ( clk_i                         ),
    .rst_src_ni ( rst_ni                        ),
    .clk_dst_i  ( clk_otp_i                     ),
    .rst_dst_ni ( rst_otp_ni                    ),
    .req_chk_i  ( 1'b1                          ),
    .src_req_i  ( key_req                       ),
    .src_ack_o  ( key_ack                       ),
    .dst_req_o  ( icache_otp_key_o.req          ),
    .dst_ack_i  ( icache_otp_key_i.ack          ),
    .data_i     ( {icache_otp_key_i.key,
                   icache_otp_key_i.nonce[lowrisc_ibex_pkg::SCRAMBLE_NONCE_W-1:0],
                   icache_otp_key_i.seed_valid} ),
    .data_o     ( {key,
                   nonce,
                   unused_seed_valid}           )
  );

  logic unused_nonce;
  assign unused_nonce = |icache_otp_key_i.nonce;

  // Local fetch enable control.
  // Whenever a fatal core error is seen disable local fetch enable.
  lowrisc_lc_ctrl_pkg::lc_tx_t local_fetch_enable_d, local_fetch_enable_q;

  assign local_fetch_enable_d = fatal_core_err ? lowrisc_lc_ctrl_pkg::Off : local_fetch_enable_q;

  lowrisc_prim_lc_sender #(
    .AsyncOn(1), // this instantiates a register
    .ResetValueIsOn(1)
  ) u_prim_lc_sender (
    .clk_i,
    .rst_ni,
    .lc_en_i(local_fetch_enable_d),
    .lc_en_o(local_fetch_enable_q)
  );

  // Multibit AND computation for fetch enable. Fetch is only enabled when local fetch enable,
  // lifecycle CPU enable and power manager CPU enable are all enabled.
  lowrisc_lc_ctrl_pkg::lc_tx_t fetch_enable;
  assign fetch_enable = lowrisc_lc_ctrl_pkg::lc_tx_and_hi(local_fetch_enable_q,
                                                  lowrisc_lc_ctrl_pkg::lc_tx_and_hi(lc_cpu_en[0],
                                                                            pwrmgr_cpu_en[0]));

  lowrisc_prim_mubi_pkg::mubi4_t mcounteren_writable_mubi4;
  lowrisc_ibex_pkg::ibex_mubi_t mcounteren_writable_ibex;
  assign mcounteren_writable_mubi4 = lowrisc_prim_mubi_pkg::mubi4_t'(reg2hw.mcounteren_writable.q);
  // Convert the mubi4 to ibex_mubi. They are both four bit, but with different encodings.
  assign mcounteren_writable_ibex = mcounteren_writable_mubi4 == lowrisc_prim_mubi_pkg::MuBi4True ?
                                    lowrisc_ibex_pkg::IbexMuBiOn : lowrisc_ibex_pkg::IbexMuBiOff;

  lowrisc_ibex_pkg::crash_dump_t crash_dump;
  lowrisc_ibex_top #(
    .PMPEnable                   ( PMPEnable                ),
    .PMPGranularity              ( PMPGranularity           ),
    .PMPNumRegions               ( PMPNumRegions            ),
    .MHPMCounterNum              ( MHPMCounterNum           ),
    .MHPMCounterWidth            ( MHPMCounterWidth         ),
    .PMPRstCfg                   ( PMPRstCfg                ),
    .PMPRstAddr                  ( PMPRstAddr               ),
    .PMPRstMsecCfg               ( PMPRstMsecCfg            ),
    .RV32E                       ( RV32E                    ),
    .RV32M                       ( RV32M                    ),
    .RV32B                       ( RV32B                    ),
    .RV32ZC                      ( RV32ZC                   ),
    .RegFile                     ( RegFile                  ),
    .BranchTargetALU             ( BranchTargetALU          ),
    .WritebackStage              ( WritebackStage           ),
    .ICache                      ( ICache                   ),
    // Our automatic SEC_CM label check doesn't look at vendored code so the SEC_CM labels need
    // to be mentioned here. The real locations can be found by grepping the vendored code.
    // TODO(#10071): this should be fixed.
    // SEC_CM: ICACHE.MEM.INTEGRITY
    .ICacheECC                   ( ICacheECC                ),
    // SEC_CM: ICACHE.MEM.SCRAMBLE, SCRAMBLE.KEY.SIDELOAD
    .ICacheScramble              ( ICacheScramble           ),
    // Reduce the number of PRINCE half rounds to 2 (5 effective rounds) to ease timing. This is
    // acceptable for the instruction cache, whereas 3 half rounds (7 effective rounds) are used
    // elsewhere in the design.
    .ICacheScrNumPrinceRoundsHalf( 2                        ),
    .BranchPredictor             ( BranchPredictor          ),
    .DbgTriggerEn                ( DbgTriggerEn             ),
    .DbgHwBreakNum               ( DbgHwBreakNum            ),
    // SEC_CM: LOGIC.SHADOW
    // SEC_CM: PC.CTRL_FLOW.CONSISTENCY, CTRL_FLOW.UNPREDICTABLE, CORE.DATA_REG_SW.SCA
    // SEC_CM: EXCEPTION.CTRL_FLOW.GLOBAL_ESC, EXCEPTION.CTRL_FLOW.LOCAL_ESC
    // SEC_CM: DATA_REG_SW.INTEGRITY, DATA_REG_SW.GLITCH_DETECT
    .SecureIbex                  ( SecureIbex               ),
    .LockstepOffset              ( LockstepOffset           ),
    .RndCnstLfsrSeed             ( RndCnstLfsrSeed          ),
    .RndCnstLfsrPerm             ( RndCnstLfsrPerm          ),
    .RndCnstIbexKey              ( RndCnstIbexKeyDefault    ),
    .RndCnstIbexNonce            ( RndCnstIbexNonceDefault  ),
    .DmBaseAddr                  ( DmBaseAddr               ),
    .DmAddrMask                  ( DmAddrMask               ),
    .DmHaltAddr                  ( DmHaltAddr               ),
    .DmExceptionAddr             ( DmExceptionAddr          ),
    .CsrMvendorId                ( CsrMvendorId             ),
    .CsrMimpId                   ( CsrMimpId                )
  ) u_core (
    .clk_i              (ibex_top_clk_i),
    .rst_ni,


    .test_en_i          (lowrisc_prim_mubi_pkg::mubi4_test_true_strict(scanmode_i)),
    .scan_rst_ni,

    .ram_cfg_icache_tag_i,
    .ram_cfg_icache_tag_o,
    .ram_cfg_icache_data_i,
    .ram_cfg_icache_data_o,

    .hart_id_i,
    .boot_addr_i,

    .instr_req_o        (main_core_instr_req),
    .instr_gnt_i        (main_core_instr_gnt_ibex),
    .instr_rvalid_i     (main_core_instr_rvalid),
    .instr_addr_o       (main_core_instr_addr),
    .instr_rdata_i      (main_core_instr_rdata),
    .instr_rdata_intg_i (main_core_instr_rdata_intg),
    .instr_err_i        (main_core_instr_err),

    .data_req_o         (main_core_data_req),
    .data_gnt_i         (main_core_data_gnt),
    .data_rvalid_i      (main_core_data_rvalid),
    .data_we_o          (main_core_data_we),
    .data_be_o          (main_core_data_be),
    .data_addr_o        (main_core_data_addr),
    .data_wdata_o       (main_core_data_wdata),
    .data_wdata_intg_o  (main_core_data_wdata_intg),
    .data_rdata_i       (main_core_data_rdata),
    .data_rdata_intg_i  (main_core_data_rdata_intg),
    .data_err_i         (main_core_data_err),

    .irq_software_i     ( irq_software     ),
    .irq_timer_i        ( irq_timer        ),
    .irq_external_i     ( irq_external     ),
    .irq_fast_i         ( '0               ),
    .irq_nm_i           ( irq_nm           ),

    .debug_req_i,
    .crash_dump_o       ( crash_dump       ),

    // icache scramble interface
    .scramble_key_valid_i (key_ack),
    .scramble_key_i       (key),
    .scramble_nonce_i     (nonce),
    .scramble_req_o       (key_req),

    // double fault
    .double_fault_seen_o  (double_fault),


    // SEC_CM: FETCH.CTRL.LC_GATED
    .fetch_enable_i         (fetch_enable),
    .mcounteren_writable_i  (mcounteren_writable_ibex),
    .alert_minor_o          (alert_minor),
    .alert_major_internal_o (alert_major_internal),
    .alert_major_bus_o      (alert_major_bus),
    .core_sleep_o           (core_sleep),

    // Lockstep outputs.
    .lockstep_cmp_en_o        (core_lockstep_cmp_en),

    // Shadow core data interface outputs.
    .data_req_shadow_o        (shadow_core_data_req),
    .data_we_shadow_o         (shadow_core_data_we),
    .data_be_shadow_o         (shadow_core_data_be),
    .data_addr_shadow_o       (shadow_core_data_addr),
    .data_wdata_shadow_o      (shadow_core_data_wdata),
    .data_wdata_intg_shadow_o (shadow_core_data_wdata_intg),

    // Shadow core instruction interface outputs.
    .instr_req_shadow_o       (shadow_core_instr_req),
    .instr_addr_shadow_o      (shadow_core_instr_addr)
  );

  logic core_sleep_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      core_sleep_q <= '0;
    end else begin
      core_sleep_q <= core_sleep;
    end
  end

  lowrisc_prim_buf #(
    .Width(1)
  ) u_core_sleeping_buf (
    .in_i(core_sleep_q),
    .out_o(pwrmgr_o.core_sleeping)
  );



  logic prev_valid;
  logic [31:0] prev_exception_pc;
  logic [31:0] prev_exception_addr;

  assign crash_dump_o.current = crash_dump;
  assign crash_dump_o.prev_valid = prev_valid;
  assign crash_dump_o.prev_exception_pc = prev_exception_pc;
  assign crash_dump_o.prev_exception_addr = prev_exception_addr;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      prev_valid <= '0;
      prev_exception_pc <= '0;
      prev_exception_addr <= '0;
    end else if (double_fault) begin
      prev_valid <= 1'b1;
      prev_exception_pc <= crash_dump.exception_pc;
      prev_exception_addr <= crash_dump.exception_addr;
    end
  end

  // Add an optional pipeline stage between Ibex and the address translation
  if (InstructionPipeline) begin : gen_instr_req_pipe
    // Request is granted for Ibex if the pipeline's request is granted or if the pipeline is empty
    assign main_core_instr_gnt_ibex = main_core_instr_gnt || !main_core_instr_req_q;
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        main_core_instr_req_q  <= 1'b0;
        main_core_instr_addr_q <= 32'h0;
      end else if (main_core_instr_gnt_ibex) begin
        // The request is captured if the pipeline's request is granted or if the pipeline is empty
        main_core_instr_req_q  <= main_core_instr_req;
        // Only capture the address if the request is valid
        if (main_core_instr_req) begin
          main_core_instr_addr_q <= main_core_instr_addr;
        end
      end
    end
  end else begin : gen_no_instr_req_pipe
    assign main_core_instr_req_q = main_core_instr_req;
    assign main_core_instr_addr_q = main_core_instr_addr;
    assign main_core_instr_gnt_ibex = main_core_instr_gnt;
  end

  //
  // Convert ibex data/instruction bus to TL-UL
  //
  logic [31:0] main_core_instr_addr_trans;
  lowrisc_rv_core_ibex_addr_trans #(
    .AddrWidth(32),
    .NumRegions(NumRegions)
  ) u_ibus_trans (
    .clk_i,
    .rst_ni(addr_trans_rst_ni),
    .region_cfg_i(ibus_region_cfg),
    .addr_i(main_core_instr_addr_q),
    .addr_o(main_core_instr_addr_trans)
  );

  logic [6:0]  instr_wdata_intg;
  logic [lowrisc_top_pkg::TL_DW-1:0] unused_data;
  // tl_adapter_host_i_ibex only reads instruction. a_data is always 0
  assign {instr_wdata_intg, unused_data} = lowrisc_prim_secded_pkg::prim_secded_inv_39_32_enc('0);
  // SEC_CM: BUS.INTEGRITY
  lowrisc_tlul_adapter_host #(
    .MAX_REQS(NumOutstandingReqs),
    // if secure ibex is not set, data integrity is not generated
    // from ibex, therefore generate it in the gasket instead.
    .EnableDataIntgGen(~SecureIbex)
  ) tl_adapter_host_i_ibex (
    .clk_i,
    .rst_ni,
    .req_i        (main_core_instr_req_q),
    .instr_type_i (lowrisc_prim_mubi_pkg::MuBi4True),
    .gnt_o        (main_core_instr_gnt),
    .addr_i       (main_core_instr_addr_trans),
    .we_i         (1'b0),
    .wdata_i      (32'b0),
    .wdata_intg_i (instr_wdata_intg),
    .be_i         (4'hF),
    .user_rsvd_i  (TlulHostUserRsvdBits),
    .valid_o      (main_core_instr_rvalid),
    .rdata_o      (main_core_instr_rdata),
    .rdata_intg_o (main_core_instr_rdata_intg),
    .err_o        (main_core_instr_err),
    .intg_err_o   (ibus_intg_err),
    .tl_o         (tl_i_ibex2fifo),
    .tl_i         (tl_i_fifo2ibex)
  );

  lowrisc_tlul_fifo_sync #(
    .ReqPass(FifoPass),
    .RspPass(FifoPass),
    .ReqDepth(FifoDepth),
    .RspDepth(FifoDepth)
  ) fifo_i (
    .clk_i,
    .rst_ni,
    .tl_h_i      (tl_i_ibex2fifo),
    .tl_h_o      (tl_i_fifo2ibex),
    .tl_d_o      (corei_tl_h_o),
    .tl_d_i      (corei_tl_h_i),
    .spare_req_i (1'b0),
    .spare_req_o (),
    .spare_rsp_i (1'b0),
    .spare_rsp_o ());

  /////////////////////////////////////////////////////
  // Main Core Address Translation and TL-UL Adapter //
  ////////////////////////////////////////////////////
  logic [31:0] main_core_data_addr_trans;
  lowrisc_rv_core_ibex_addr_trans #(
    .AddrWidth(32),
    .NumRegions(NumRegions)
  ) u_dbus_trans (
    .clk_i,
    .rst_ni(addr_trans_rst_ni),
    .region_cfg_i(dbus_region_cfg),
    .addr_i(main_core_data_addr),
    .addr_o(main_core_data_addr_trans)
  );

  // SEC_CM: BUS.INTEGRITY
  lowrisc_tlul_adapter_host #(
    .MAX_REQS(2),
    .EnableDataIntgGen(~SecureIbex)
  ) tl_adapter_host_d_ibex (
    .clk_i,
    .rst_ni,
    .req_i        (main_core_data_req),
    .instr_type_i (lowrisc_prim_mubi_pkg::MuBi4False),
    .gnt_o        (main_core_data_gnt),
    .addr_i       (main_core_data_addr_trans),
    .we_i         (main_core_data_we),
    .wdata_i      (main_core_data_wdata),
    .wdata_intg_i (main_core_data_wdata_intg),
    .be_i         (main_core_data_be),
    .user_rsvd_i  (TlulHostUserRsvdBits),
    .valid_o      (main_core_data_rvalid),
    .rdata_o      (main_core_data_rdata),
    .rdata_intg_o (main_core_data_rdata_intg),
    .err_o        (main_core_data_err),
    .intg_err_o   (dbus_intg_err),
    .tl_o         (tl_d_ibex2fifo_main_core),
    .tl_i         (tl_d_fifo2ibex)
  );

  lowrisc_tlul_fifo_sync #(
    .ReqPass(FifoPass),
    .RspPass(FifoPass),
    .ReqDepth(FifoDepth),
    .RspDepth(FifoDepth)
  ) fifo_d (
    .clk_i,
    .rst_ni,
    .tl_h_i      (tl_d_ibex2fifo_main_core),
    .tl_h_o      (tl_d_fifo2ibex),
    .tl_d_o      (tl_d_fifo2gate),
    .tl_d_i      (tl_d_gate2fifo),
    .spare_req_i (1'b0),
    .spare_req_o (),
    .spare_rsp_i (1'b0),
    .spare_rsp_o ());

  // Gate any pending requests on escalation
  lowrisc_tlul_lc_gate #(
    .Outstanding(NumOutstandingReqs),
    .NumGatesPerDirection(1),
    // Don't return an error. Only interested in blocking a request at this stage
    .ReturnBlankResp(1)
  ) u_tlul_lc_gate_cored (
    .clk_i,
    .rst_ni,
    .tl_h2d_i       (tl_d_fifo2gate),
    .tl_d2h_o       (tl_d_gate2fifo),
    .tl_h2d_o       (cored_tl_h_o),
    .tl_d2h_i       (cored_tl_h_i),
    .flush_req_i    (1'b0),
    .flush_ack_o    (),
    .resp_pending_o (),
    .lc_en_i        (lc_cpu_en[1]),
    .err_o          (tlul_lc_gate_core_d_error)
  );



  //////////////////////////////////
  // Peripheral functions
  //////////////////////////////////

  logic cfg_reg_intg_err;
  logic cfg_reg_intg_err_shadow;
  lowrisc_tlul_pkg::tl_h2d_t tl_win_h2d;
  lowrisc_tlul_pkg::tl_d2h_t tl_win_d2h;
  lowrisc_rv_core_ibex_cfg_reg_top u_reg_cfg (
    .clk_i,
    .rst_ni,
    .tl_i(cfg_tl_d_i),
    .tl_o(cfg_tl_d_o),
    .reg2hw,
    .hw2reg,
    .intg_err_o (cfg_reg_intg_err),
    .tl_win_o(tl_win_h2d),
    .tl_win_i(tl_win_d2h)
  );

  ///////////////////////
  // Region assignments
  ///////////////////////

  logic [NumRegions-1:0] unused_ibus_region_cfg_qe;
  for(genvar i = 0; i < NumRegions; i++) begin : gen_ibus_region_cfgs
    assign ibus_region_cfg[i].en = reg2hw.ibus_addr_en[i].q;
    assign ibus_region_cfg[i].matching_region = reg2hw.ibus_addr_matching[i].q;
    assign ibus_region_cfg[i].remap_addr = reg2hw.ibus_remap_addr[i].q;
    // Tie off the unused `qe` signals as they are only used in the shadow cfg registers in the
    // TLUL lockstep.
    assign unused_ibus_region_cfg_qe[i] = ^{reg2hw.ibus_addr_en[i].qe,
                                            reg2hw.ibus_addr_matching[i].qe,
                                            reg2hw.ibus_remap_addr[i].qe};
  end

  logic [NumRegions-1:0] unused_dbus_region_cfg_qe;
  for(genvar i = 0; i < NumRegions; i++) begin : gen_dbus_region_cfgs
    assign dbus_region_cfg[i].en = reg2hw.dbus_addr_en[i].q;
    assign dbus_region_cfg[i].matching_region = reg2hw.dbus_addr_matching[i].q;
    assign dbus_region_cfg[i].remap_addr = reg2hw.dbus_remap_addr[i].q;
    // Tie off the unused `qe` signals as they are only used in the shadow cfg registers in the
    // TLUL lockstep.
    assign unused_dbus_region_cfg_qe[i] = ^{reg2hw.dbus_addr_en[i].qe,
                                            reg2hw.dbus_addr_matching[i].qe,
                                            reg2hw.dbus_remap_addr[i].qe};
  end

  ///////////////////////
  // Error assignment
  ///////////////////////

  assign fatal_intg_err = fatal_intg_event;
  assign fatal_core_err = fatal_core_event;
  assign recov_core_err = recov_core_event;

  assign hw2reg.err_status.reg_intg_err.d = 1'b1;
  assign hw2reg.err_status.reg_intg_err.de = cfg_reg_intg_err | cfg_reg_intg_err_shadow;
  assign hw2reg.err_status.fatal_intg_err.d = 1'b1;
  assign hw2reg.err_status.fatal_intg_err.de = fatal_intg_err;
  assign hw2reg.err_status.fatal_core_err.d = 1'b1;
  assign hw2reg.err_status.fatal_core_err.de = fatal_core_err;
  assign hw2reg.err_status.recov_core_err.d = 1'b1;
  assign hw2reg.err_status.recov_core_err.de = recov_core_err;

  ///////////////////////
  // Alert generation
  ///////////////////////

  logic [NumAlerts-1:0] alert_test;
  assign alert_test[0] = reg2hw.alert_test.fatal_sw_err.q &
                         reg2hw.alert_test.fatal_sw_err.qe;
  assign alert_test[1] = reg2hw.alert_test.recov_sw_err.q &
                         reg2hw.alert_test.recov_sw_err.qe;
  assign alert_test[2] = reg2hw.alert_test.fatal_hw_err.q &
                         reg2hw.alert_test.fatal_hw_err.qe;
  assign alert_test[3] = reg2hw.alert_test.recov_hw_err.q &
                         reg2hw.alert_test.recov_hw_err.qe;

  localparam bit [NumAlerts-1:0] AlertFatal = '{1'b0, 1'b1, 1'b0, 1'b1};

  logic [NumAlerts-1:0] alert_events;
  logic [NumAlerts-1:0] alert_acks;

  import lowrisc_prim_mubi_pkg::mubi4_test_true_loose;
  import lowrisc_prim_mubi_pkg::mubi4_t;
  assign alert_events[0] = mubi4_test_true_loose(mubi4_t'(reg2hw.sw_fatal_err.q));
  assign alert_events[1] = mubi4_test_true_loose(mubi4_t'(reg2hw.sw_recov_err.q));
  assign alert_events[2] = cfg_reg_intg_err | cfg_reg_intg_err_shadow |
                           fatal_intg_err | fatal_core_err;
  assign alert_events[3] = recov_core_err;

  logic unused_alert_acks;
  assign unused_alert_acks = |alert_acks;

  // recoverable alerts are sent once and silenced until activated again.
  assign hw2reg.sw_recov_err.de = alert_acks[1];
  assign hw2reg.sw_recov_err.d = lowrisc_prim_mubi_pkg::MuBi4False;

  for (genvar i = 0; i < NumAlerts; i++) begin : gen_alert_senders
    lowrisc_prim_alert_sender #(
      .AsyncOn(AlertAsyncOn[0]),
      .SkewCycles(AlertSkewCycles),
      .IsFatal(AlertFatal[i])
    ) u_alert_sender (
      .clk_i,
      .rst_ni,
      .alert_test_i(alert_test[i]),
      .alert_req_i(alert_events[i]),
      .alert_ack_o(alert_acks[i]),
      .alert_state_o(),
      .alert_rx_i(alert_rx_i[i]),
      .alert_tx_o(alert_tx_o[i])
    );
  end

  //////////////
  // RND Data //
  //////////////

  logic [31:0] rnd_data_q, rnd_data_d;
  logic rnd_valid_q, rnd_valid_d;
  logic rnd_fips_q, rnd_fips_d;
  logic edn_req;
  logic [31:0] edn_data;
  logic edn_ack;
  logic edn_fips;

  always_comb begin
    rnd_valid_d = rnd_valid_q;
    rnd_data_d  = rnd_data_q;
    rnd_fips_d  = rnd_fips_q;

    if (reg2hw.rnd_data.re) begin
      rnd_valid_d = '0;
      rnd_data_d  = '0;
      rnd_fips_d  = '0;
    end else if (edn_req && edn_ack) begin
      rnd_valid_d = 1'b1;
      rnd_data_d  = edn_data;
      rnd_fips_d  = edn_fips;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rnd_valid_q <= '0;
      rnd_data_q  <= '0;
      rnd_fips_q  <= '0;
    end else begin
      rnd_valid_q <= rnd_valid_d;
      rnd_data_q  <= rnd_data_d;
      rnd_fips_q  <= rnd_fips_d;
    end
  end

  assign edn_req = ~rnd_valid_q;

  lowrisc_prim_edn_req #(
    .OutWidth(32)
  ) u_edn_if (
    .clk_i,
    .rst_ni,
    .req_chk_i(1'b1),
    .req_i(edn_req),
    .ack_o(edn_ack),
    .data_o(edn_data),
    .fips_o(edn_fips),
    .err_o(),
    .clk_edn_i,
    .rst_edn_ni,
    .edn_o,
    .edn_i
  );

  assign hw2reg.rnd_data.d                  = rnd_data_q;
  assign hw2reg.rnd_status.rnd_data_valid.d = rnd_valid_q;
  assign hw2reg.rnd_status.rnd_data_fips.d  = rnd_fips_q;

  logic unused_reg2hw;
  assign unused_reg2hw = |reg2hw.rnd_data.q;


  // fpga build info hook-up
  assign hw2reg.fpga_info.d = fpga_info_i;

  if (SecureIbex) begin : gen_tlul_lockstep
    /////////////////////////////////////////////////////
    // Shadow Core instruction and data region config. //
    /////////////////////////////////////////////////////

    rv_core_ibex_cfg_reg2hw_t reg2hw_shadow;
    region_cfg_t [NumRegions-1:0] ibus_region_cfg_shadow;
    region_cfg_t [NumRegions-1:0] dbus_region_cfg_shadow;
    logic        [NumRegions-1:0] ibus_region_cfg_shadow_changed;
    logic        [NumRegions-1:0] dbus_region_cfg_shadow_changed;

    lowrisc_tlul_pkg::tl_h2d_t unused_tl_win_h2d_shadow;
    lowrisc_tlul_pkg::tl_d2h_t unused_cfg_tl_d_shadow;

    lowrisc_rv_core_ibex_cfg_reg_top u_reg_cfg_shadow (
      .clk_i,
      .rst_ni,
      .tl_i       (cfg_tl_d_i),
      .tl_o       (unused_cfg_tl_d_shadow),
      .reg2hw     (reg2hw_shadow),
      .hw2reg     (rv_core_ibex_cfg_hw2reg_t'('0)),
      .intg_err_o (cfg_reg_intg_err_shadow),
      .tl_win_o   (unused_tl_win_h2d_shadow),
      .tl_win_i   (tl_win_d2h)
    );

    for(genvar i = 0; i < NumRegions; i++) begin : gen_ibus_region_cfg_shadows
      assign ibus_region_cfg_shadow[i].en = reg2hw_shadow.ibus_addr_en[i].q;
      assign ibus_region_cfg_shadow[i].matching_region = reg2hw_shadow.ibus_addr_matching[i].q;
      assign ibus_region_cfg_shadow[i].remap_addr = reg2hw_shadow.ibus_remap_addr[i].q;
      assign ibus_region_cfg_shadow_changed[i] = reg2hw_shadow.ibus_addr_en[i].qe |
                                                 reg2hw_shadow.ibus_addr_matching[i].qe |
                                                 reg2hw_shadow.ibus_remap_addr[i].qe;
    end

    for(genvar i = 0; i < NumRegions; i++) begin : gen_dbus_region_cfg_shadows
      assign dbus_region_cfg_shadow[i].en = reg2hw_shadow.dbus_addr_en[i].q;
      assign dbus_region_cfg_shadow[i].matching_region = reg2hw_shadow.dbus_addr_matching[i].q;
      assign dbus_region_cfg_shadow[i].remap_addr = reg2hw_shadow.dbus_remap_addr[i].q;
      assign dbus_region_cfg_shadow_changed[i] = reg2hw_shadow.dbus_addr_en[i].qe |
                                                 reg2hw_shadow.dbus_addr_matching[i].qe |
                                                 reg2hw_shadow.dbus_remap_addr[i].qe;
    end

    // When the dbus or ibus region configuration register shadow has been updated, which is
