module lowrisc_csrng
 import lowrisc_csrng_pkg::*;
 import lowrisc_csrng_reg_pkg::*;
#(
  parameter lowrisc_aes_pkg::sbox_impl_e SBoxImpl = lowrisc_aes_pkg::SBoxImplCanright,
  parameter logic [NumAlerts-1:0] AlertAsyncOn = {NumAlerts{1'b1}},
  // Number of cycles a differential skew is tolerated on the alert signal
  parameter int unsigned AlertSkewCycles = 1,
  parameter cs_keymgr_div_t RndCnstCsKeymgrDivNonProduction = CsKeymgrDivWidth'(0),
  parameter cs_keymgr_div_t RndCnstCsKeymgrDivProduction = CsKeymgrDivWidth'(0),

  localparam int unsigned NumHwApps = NumApps - 1 // derived parameter
) (
  input  logic clk_i,
  input  logic rst_ni,

  // TileLink Bus Interface
  input  lowrisc_tlul_pkg::tl_h2d_t tl_i,
  output lowrisc_tlul_pkg::tl_d2h_t tl_o,

  // OTP Interface
  // SEC_CM: INTERSIG.MUBI
  input  lowrisc_prim_mubi_pkg::mubi8_t otp_en_csrng_sw_app_read_i,

  // Life Cycle Broadcast Inputs
  input  lowrisc_lc_ctrl_pkg::lc_tx_t lc_hw_debug_en_i,

  // Entropy Source Interface
  output lowrisc_entropy_src_pkg::entropy_src_hw_if_req_t entropy_src_hw_if_o,
  input  lowrisc_entropy_src_pkg::entropy_src_hw_if_rsp_t entropy_src_hw_if_i,

  // Application Interfaces
  input  csrng_req_t [NumHwApps-1:0] csrng_cmd_i,
  output csrng_rsp_t [NumHwApps-1:0] csrng_cmd_o,

  // Alerts
  input  lowrisc_prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i,
  output lowrisc_prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o,

  // Interrupts
  output logic intr_cs_cmd_req_done_o,
  output logic intr_cs_entropy_req_o,
  output logic intr_cs_hw_inst_exc_o,
  output logic intr_cs_fatal_err_o
);

  csrng_reg2hw_t reg2hw;
  csrng_hw2reg_t hw2reg;

  logic [NumAlerts-1:0] alert_test;
  logic [NumAlerts-1:0] alert;

  logic [NumAlerts-1:0] intg_err_alert;
  assign intg_err_alert[0] = 1'b0;

  // SEC_CM: CONFIG.REGWEN
  // SEC_CM: TILE_LINK.BUS.INTEGRITY

  lowrisc_csrng_reg_top u_reg (
    .clk_i,
    .rst_ni,
    .tl_i,
    .tl_o,
    .reg2hw,
    .hw2reg,
    .intg_err_o(intg_err_alert[1])
  );

  lowrisc_csrng_core #(
    .SBoxImpl(SBoxImpl),
    .NumHwApps(NumHwApps),
    .RndCnstCsKeymgrDivNonProduction(RndCnstCsKeymgrDivNonProduction),
    .RndCnstCsKeymgrDivProduction(RndCnstCsKeymgrDivProduction)
  ) u_csrng_core (
    .clk_i,
    .rst_ni,
    .reg2hw,
    .hw2reg,

    // misc inputs
    .otp_en_csrng_sw_app_read_i(otp_en_csrng_sw_app_read_i),
    .lc_hw_debug_en_i,

    // Entropy Interface
    .entropy_src_hw_if_o,
    .entropy_src_hw_if_i,

    // Application Interfaces
    .csrng_cmd_i,
    .csrng_cmd_o,

    // Alerts
    .recov_alert_test_o(alert_test[0]),
    .fatal_alert_test_o(alert_test[1]),
    .recov_alert_o(alert[0]),
    .fatal_alert_o(alert[1]),

    .intr_cs_cmd_req_done_o,
    .intr_cs_entropy_req_o,
    .intr_cs_hw_inst_exc_o,
    .intr_cs_fatal_err_o
  );


  ///////////////////////////
  // Alert generation
  ///////////////////////////
  for (genvar i = 0; i < NumAlerts; i++) begin : gen_alert_tx
    lowrisc_prim_alert_sender #(
      .AsyncOn(AlertAsyncOn[i]),
      .SkewCycles(AlertSkewCycles),
      .IsFatal(i)
    ) u_prim_alert_sender (
      .clk_i,
      .rst_ni,
      .alert_test_i  ( alert_test[i]                 ),
      .alert_req_i   ( alert[i] || intg_err_alert[i] ),
      .alert_ack_o   (                               ),
      .alert_state_o (                               ),
      .alert_rx_i    ( alert_rx_i[i]                 ),
      .alert_tx_o    ( alert_tx_o[i]                 )
    );
  end


  // Assertions





  // Application Interface Asserts
  for (genvar i = 0; i < NumHwApps; i = i+1) begin : gen_app_if_asserts












  end : gen_app_if_asserts

  // Alerts














  for (genvar i = 0; i < NumHwApps + 1; i++) begin : gen_cnt_asserts













  end
















  for (genvar i = 0; i < lowrisc_aes_pkg::Sp2VWidth; i++) begin : gen_aes_cipher_control_fsm_svas
    if (lowrisc_aes_pkg::SP2V_LOGIC_HIGH[i] == 1'b1) begin : gen_aes_cipher_control_fsm_svas_p






    end else begin : gen_aes_cipher_control_fsm_svas_n






    end
  end

  // Alert assertions for reg_we onehot check








  // The total number of application interfaces defined in the hjson must be at least two:
  // One SW interface and at least one HW interface. Zero HW interfaces is currently not supported.

endmodule
