// OTBN mask accelerator interface

module lowrisc_otbn_mai
  import lowrisc_otbn_pkg::*;
#(
  // Masking accelerator interface will not randomize operand start indexes
  parameter bit SecFixMaiOpSeq = 1'b0
)(
  input  logic clk_i,
  input  logic rst_ni,

  // Secure wipe
  input  logic sec_wipe_mai_i,
  input  logic sec_wipe_running_i,

  // CSR write
  input  logic        ispr_mai_ctrl_wr_i,
  input  logic [31:0] ispr_mai_ctrl_wdata_i,

  // CSR read
  output logic [31:0] ispr_mai_ctrl_rdata_o,
  output logic [31:0] ispr_mai_status_rdata_o,

  // WSR write
  input  logic               ispr_mai_in0_s0_wr_i,
  input  logic               sec_wipe_ispr_mai_in0_s0_i,
  input  logic [ExtWLEN-1:0] ispr_mai_in0_s0_wdata_i,
  input  logic               ispr_mai_in0_s1_wr_i,
  input  logic               sec_wipe_ispr_mai_in0_s1_i,
  input  logic [ExtWLEN-1:0] ispr_mai_in0_s1_wdata_i,
  input  logic               ispr_mai_in1_s0_wr_i,
  input  logic               sec_wipe_ispr_mai_in1_s0_i,
  input  logic [ExtWLEN-1:0] ispr_mai_in1_s0_wdata_i,
  input  logic               ispr_mai_in1_s1_wr_i,
  input  logic               sec_wipe_ispr_mai_in1_s1_i,
  input  logic [ExtWLEN-1:0] ispr_mai_in1_s1_wdata_i,
  input  logic               ispr_mai_res_s0_wr_i,
  input  logic               sec_wipe_ispr_mai_res_s0_i,
  input  logic [ExtWLEN-1:0] ispr_mai_res_s0_wdata_i,
  input  logic               ispr_mai_res_s1_wr_i,
  input  logic               sec_wipe_ispr_mai_res_s1_i,
  input  logic [ExtWLEN-1:0] ispr_mai_res_s1_wdata_i,

  // WSR read
  output logic [ExtWLEN-1:0] ispr_mai_in0_s0_rdata_o,
  output logic [ExtWLEN-1:0] ispr_mai_in0_s1_rdata_o,
  output logic [ExtWLEN-1:0] ispr_mai_in1_s0_rdata_o,
  output logic [ExtWLEN-1:0] ispr_mai_in1_s1_rdata_o,
  output logic [ExtWLEN-1:0] ispr_mai_res_s0_rdata_o,
  output logic [ExtWLEN-1:0] ispr_mai_res_s1_rdata_o,

  // Connection to MOD register with integrity data
  input  logic [ExtWLEN-1:0] ispr_mod_intg_i,

  // Error
  output logic mai_software_error_o,
  output logic mai_reg_intg_violation_err_o,
  output logic mai_state_err_o,

  input  logic [UrndLen-1:0] urnd_data_i
);

  ///////////
  // Types //
  ///////////

  localparam int unsigned IsprMaiCtrlResWidth = 32'd32 - 32'd1 - MaskOpWidth;

  typedef struct packed {
    logic [IsprMaiCtrlResWidth-1:0] rsvd;
    mask_op_e                       op;
    logic                           start;
  } ispr_mai_ctrl_t;

  typedef struct packed {
    logic [31-2:0] rsvd;
    logic          input_ready;
    logic          busy;
  } ispr_mai_status_t;

  typedef struct packed {
    logic out_cnt;
    logic in_cnt;
    logic ma_fifo;
    logic ma_cnt;
  } mai_state_err_t;

  typedef struct packed {
    logic [1:0] mod;
    logic [1:0] in0_s0;
    logic [1:0] in0_s1;
    logic [1:0] in1_s0;
    logic [1:0] in1_s1;
  } mai_reg_intg_violation_err_t;

  typedef struct packed {
    logic invalid_op;
    logic busy_start;
    logic busy_write;
    logic rsvd_csr_write;
  } ispr_mai_sw_err_t;

  localparam int unsigned MaiCntWidth = lowrisc_prim_util_pkg::vbits(BaseWordsPerWLEN);

  typedef logic [MaiCntWidth-1:0] mai_cnt_t;

  typedef struct packed {
    logic [MaiCntWidth-1:0] cnt;
    logic [31:0]            mask_1;
    logic [31:0]            mask_0;
    logic [MaRndLen-1:0]    urnd;
  } mai_ma_urnd_t;


  /////////////
  // Signals //
  /////////////

  // PRNG input
  otbn_ispr_urnd_t mai_ispr_urnd;
  mai_ma_urnd_t    mai_ma_urnd;
  logic            unused_urnd;

  // Error signals
  mai_reg_intg_violation_err_t mai_reg_intg_violation_err;
  logic                        mai_reg_intg_violation_err_masked;
  mai_state_err_t              mai_state_err;

  // Masking accelerator signals
  logic                 ma_in_valid_q;
  logic                 ma_in_ready;
  logic                 ma_in_consume;
  logic                 ma_out_ready;
  logic                 ma_busy_q;
  ma_sharing_t          ma_in0;
  ma_sharing_t          ma_in1;
  ma_sharing_t          ma_remask_rand;
  ma_sharing_t          ma_result;
  otbn_wide_intg_word_t ma_mod;
  ma_ele_t              ma_mod_lsw;

  // Counter load values
  mai_cnt_t cnt_load_val;

  // Input counter
  mai_cnt_t in_cnt_load_val_q;
  mai_cnt_t in_cnt_tgt;
  logic     in_cnt_overflow;
  logic     in_cnt_done;
  logic     in_cnt_set;

  // Input multiplexer
  mai_cnt_t             ispr_mai_in_mux_sel;
  otbn_base_intg_word_t ispr_mai_in0_s0_mux_out;
  otbn_base_intg_word_t ispr_mai_in0_s1_mux_out;
  otbn_base_intg_word_t ispr_mai_in1_s0_mux_out;
  otbn_base_intg_word_t ispr_mai_in1_s1_mux_out;

  // Output counter
  mai_cnt_t out_cnt_load_val_d, out_cnt_load_val_q;
  mai_cnt_t out_cnt_tgt;
  logic     out_cnt_overflow;
  logic     out_cnt_done;
  logic     out_cnt_set;

  // Output multiplexer
  mai_cnt_t                    ispr_mai_out_demux_sel;
  logic [BaseWordsPerWLEN-1:0] ispr_mai_out_demux_sel_onehot;

  otbn_base_intg_word_t ispr_mai_res_s0;
  otbn_base_intg_word_t ispr_mai_res_s1;

  // CSRs
  ispr_mai_ctrl_t   ispr_mai_ctrl_r;
  ispr_mai_ctrl_t   ispr_mai_ctrl_w;
  ispr_mai_status_t ispr_mai_status;
  logic             ma_start;
  mask_op_e         ma_mask_op_q, ma_mask_op_d;
  ispr_mai_sw_err_t ispr_mai_sw_err;

  // WSRs
  otbn_wide_intg_word_t ispr_mai_in0_s0_d, ispr_mai_in0_s0_q;
  otbn_wide_intg_word_t ispr_mai_in0_s1_d, ispr_mai_in0_s1_q;
  otbn_wide_intg_word_t ispr_mai_in1_s0_d, ispr_mai_in1_s0_q;
  otbn_wide_intg_word_t ispr_mai_in1_s1_d, ispr_mai_in1_s1_q;
  otbn_wide_intg_word_t ispr_mai_res_s0_d, ispr_mai_res_s0_q;
  otbn_wide_intg_word_t ispr_mai_res_s1_d, ispr_mai_res_s1_q;


  ////////////
  // Random //
  ////////////
  // The fields of mai_ma_urnd feed the mask accelerator:
  // urnd    (322b): rand_i, drives the HPC3 gadgets inside otbn_sec_add_mod
  // mask_0  ( 32b): remask_rand_i[0], per-handshake re-masking word for adder input share 0
  // mask_1  ( 32b): remask_rand_i[1], per-handshake re-masking word for adder input share 1
  // cnt     (  3b): seeds the batch-counter start offset
  assign mai_ma_urnd   = urnd_data_i;
  assign mai_ispr_urnd = urnd_data_i;
  assign unused_urnd   = ^mai_ispr_urnd.rsvd;


  /////////////////////////
  // Masking Accelerator //
  /////////////////////////

  lowrisc_otbn_mask_accelerator u_otbn_mask_accelerator (
    .clk_i,
    .rst_ni,
    .sec_wipe_running_i,
    .wvalid_i       (ma_in_valid_q),
    .wready_o       (ma_in_ready),
    .in0_i          (ma_in0),
    .in1_i          (ma_in1),
    .rand_i         (mai_ma_urnd.urnd),
    .remask_rand_i  (ma_remask_rand),
    .mod_i          (ma_mod_lsw),
    .mask_op_i      (ma_mask_op_q),
    .rvalid_o       (ma_out_ready),
    .rready_i       (1'b0), // Internally ignored
    .result_o       (ma_result),
    .mask_fifo_err_o(mai_state_err.ma_fifo),
    .ctr_err_o      (mai_state_err.ma_cnt)
  );

  // We always push input WSR data even in the case of a secure wipe. The accelerator is usually
  // idle while a secure wipe is running. If we escalate during an active MAI operation, we will
  // feed the valid data in the input WSRs through the pipeline.
  assign ma_in0[0] = ispr_mai_in0_s0_mux_out.word;
  assign ma_in0[1] = ispr_mai_in0_s1_mux_out.word;
  assign ma_in1[0] = ispr_mai_in1_s0_mux_out.word;
  assign ma_in1[1] = ispr_mai_in1_s1_mux_out.word;

  assign ma_mod     = ispr_mod_intg_i;
  assign ma_mod_lsw = ma_mod[0].word;

  // We only use the lowest word
  logic unused_ma_mod;
  assign unused_ma_mod = ^ma_mod[BaseWordsPerWLEN-1:1];

  assign ma_remask_rand[0] = mai_ma_urnd.mask_0;
  assign ma_remask_rand[1] = mai_ma_urnd.mask_1;

  assign ma_in_consume = ma_in_valid_q & ma_in_ready;

  // Integrity check of the lowest word of ispr_mod_intg_i
  lowrisc_prim_secded_inv_39_32_dec u_prim_secded_inv_39_32_dec_mod (
    .data_i    (ma_mod[0]),
    .data_o    (/* NOT CONNECTED */),
    .syndrome_o(/* NOT CONNECTED */),
    .err_o     (mai_reg_intg_violation_err.mod)
  );

  ////////////////////
  // Input Handling //
  ////////////////////

  // The input and output counter are loaded with either a URND value during normal operation
  // or with zero during side channel analysis (`SecFixMaiOpSeq`).

  // The input counter is loaded on assertion of `sec_wipe_mai_i` or when the input counter
  // completes, see `in_cnt_set`. Parallel to the load of the input counter, the `in_cnt_load_val_q`
  // register is populated with the same URND value. This register is used to determine the target
  // value of the input counter as well as the non-secure-wipe load value of the output counter.

  // The output counter is loaded with the current URND value during secure wipes or with the value
  // stored in `in_cnt_load_val_q` during regular operation on reaching its output counter
  // target value. The register `out_cnt_load_val_q` is loaded in parallel with the output counter
  // and is used to determine the output counter's target value.

  lowrisc_prim_count #(
    .Width(MaiCntWidth),
    .PossibleActions(lowrisc_prim_count_pkg::Clr | lowrisc_prim_count_pkg::Set | lowrisc_prim_count_pkg::Incr)
  ) u_prim_count_input_word_select (
    .clk_i,
    .rst_ni,
    .clr_i             (in_cnt_overflow && !in_cnt_done && !sec_wipe_mai_i),
    .set_i             (in_cnt_set),
    .set_cnt_i         (cnt_load_val),
    .incr_en_i         (1'b1),
    .decr_en_i         (1'b0),
    .step_i            (mai_cnt_t'('d1)),
    .commit_i          (ma_in_consume || in_cnt_set),
    .cnt_o             (ispr_mai_in_mux_sel),
    .cnt_after_commit_o(/* NOT CONNECTED */),
    .err_o             (mai_state_err.in_cnt)
  );

  assign in_cnt_tgt      = (in_cnt_load_val_q - mai_cnt_t'('d1));
  assign in_cnt_done     = (ispr_mai_in_mux_sel == in_cnt_tgt) && ma_in_consume;
  assign in_cnt_overflow = ispr_mai_in_mux_sel == '1;
  assign in_cnt_set      = in_cnt_done || sec_wipe_mai_i;

  // Store initial value of input counter
  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_init_in_cnt_load_val_store
    if (!rst_ni) begin
      in_cnt_load_val_q <= '0;
    end else begin
      if (in_cnt_set) begin
        in_cnt_load_val_q <= cnt_load_val;
      end
    end
  end

  // Define the load counter value. In regular use case, this is randomized with a value from URND.
  // For side channel analyses, this randomization can be turned off using the SecFixMaiOpSeq
  // parameter.
  assign cnt_load_val = SecFixMaiOpSeq ? '0 : mai_ma_urnd.cnt;

  // Input word selection and blanking. We are allowed to use a regular multiplexer here, as
  // we anyway have leakage between the successive words inside of the masking accelerator.
  assign ispr_mai_in0_s0_mux_out = ma_in_valid_q ? ispr_mai_in0_s0_q[ispr_mai_in_mux_sel] : '0;
  assign ispr_mai_in0_s1_mux_out = ma_in_valid_q ? ispr_mai_in0_s1_q[ispr_mai_in_mux_sel] : '0;
  assign ispr_mai_in1_s0_mux_out = ma_in_valid_q ? ispr_mai_in1_s0_q[ispr_mai_in_mux_sel] : '0;
  assign ispr_mai_in1_s1_mux_out = ma_in_valid_q ? ispr_mai_in1_s1_q[ispr_mai_in_mux_sel] : '0;

  // Input word ECC checking
  lowrisc_prim_secded_inv_39_32_dec u_prim_secded_inv_39_32_dec_in0_s0 (
    .data_i    (ispr_mai_in0_s0_mux_out),
    .data_o    (/* NOT CONNECTED */),
    .syndrome_o(/* NOT CONNECTED */),
    .err_o     (mai_reg_intg_violation_err.in0_s0)
  );

  lowrisc_prim_secded_inv_39_32_dec u_prim_secded_inv_39_32_dec_in0_s1 (
    .data_i    (ispr_mai_in0_s1_mux_out),
    .data_o    (/* NOT CONNECTED */),
    .syndrome_o(/* NOT CONNECTED */),
    .err_o     (mai_reg_intg_violation_err.in0_s1)
  );

  lowrisc_prim_secded_inv_39_32_dec u_prim_secded_inv_39_32_dec_in1_s0 (
    .data_i    (ispr_mai_in1_s0_mux_out),
    .data_o    (/* NOT CONNECTED */),
    .syndrome_o(/* NOT CONNECTED */),
    .err_o     (mai_reg_intg_violation_err.in1_s0)
  );

  lowrisc_prim_secded_inv_39_32_dec u_prim_secded_inv_39_32_dec_in1_s1 (
    .data_i    (ispr_mai_in1_s1_mux_out),
    .data_o    (/* NOT CONNECTED */),
    .syndrome_o(/* NOT CONNECTED */),
    .err_o     (mai_reg_intg_violation_err.in1_s1)
  );


  /////////////////////
  // Output Handling //
  /////////////////////

  lowrisc_prim_count #(
    .Width(MaiCntWidth),
    .PossibleActions(lowrisc_prim_count_pkg::Clr | lowrisc_prim_count_pkg::Set | lowrisc_prim_count_pkg::Incr)
  ) u_prim_count_output_word_select (
    .clk_i,
    .rst_ni,
    .clr_i             (out_cnt_overflow & !out_cnt_done & !sec_wipe_mai_i),
    .set_i             (out_cnt_set),
    .set_cnt_i         (out_cnt_load_val_d),
    .incr_en_i         (1'b1),
    .decr_en_i         (1'b0),
    .step_i            (mai_cnt_t'('d1)),
    .commit_i          (ma_out_ready || out_cnt_set),
    .cnt_o             (ispr_mai_out_demux_sel),
    .cnt_after_commit_o(/* NOT CONNECTED */),
    .err_o             (mai_state_err.out_cnt)
  );

  assign out_cnt_load_val_d = sec_wipe_mai_i ? cnt_load_val : in_cnt_load_val_q;
  assign out_cnt_tgt        = (out_cnt_load_val_q - mai_cnt_t'('d1));
  assign out_cnt_done       = (ispr_mai_out_demux_sel == out_cnt_tgt) && ma_out_ready;
  assign out_cnt_overflow   = ispr_mai_out_demux_sel == '1;
  assign out_cnt_set        = out_cnt_done || sec_wipe_mai_i;

  // Store initial value of output counter
  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_init_out_cnt_load_val_store
    if (!rst_ni) begin
      out_cnt_load_val_q <= '0;
    end else begin
      if (out_cnt_set) begin
        out_cnt_load_val_q <= out_cnt_load_val_d;
      end
    end
  end

  // Output word selection signal to one hot
  // We don't write to the register if a secure wipe is ongoing
  lowrisc_prim_onehot_enc #(
    .OneHotWidth(BaseWordsPerWLEN)
  ) u_prim_onehot_enc_output_word_select (
    .in_i (ispr_mai_out_demux_sel),
    .en_i (ma_out_ready && !sec_wipe_running_i),
    .out_o(ispr_mai_out_demux_sel_onehot)
  );

  lowrisc_prim_secded_inv_39_32_enc u_prim_secded_inv_39_32_enc_res_s0 (
    .data_i(ma_result[0]),
    .data_o(ispr_mai_res_s0)
  );

  lowrisc_prim_secded_inv_39_32_enc u_prim_secded_inv_39_32_enc_res_s1 (
    .data_i(ma_result[1]),
    .data_o(ispr_mai_res_s1)
  );


  ////////////////////
  // CSR Bus Access //
  ////////////////////

  // Control write
  assign ispr_mai_ctrl_w = ispr_mai_ctrl_wdata_i;
  assign ma_start        = ispr_mai_ctrl_wr_i & ispr_mai_ctrl_w.start;

  // Status read
  assign ispr_mai_status.rsvd        = '0;
  assign ispr_mai_status.input_ready = !ma_in_valid_q;
  assign ispr_mai_status.busy        = ma_busy_q;
  assign ispr_mai_status_rdata_o     = ispr_mai_status;

  // Control read
  assign ispr_mai_ctrl_r.rsvd  = '0;
  assign ispr_mai_ctrl_r.start = 1'b0;
  assign ispr_mai_ctrl_r.op    = ma_mask_op_q;
  assign ispr_mai_ctrl_rdata_o = ispr_mai_ctrl_r;

  // Erroneous control accesses
  // The start bit and configuration may only be written when not busy.
  assign ispr_mai_sw_err.busy_start     = ma_busy_q & ispr_mai_ctrl_wr_i;
  // There may not be a write to the input WSRs whilst an execution is ongoing. This is required to
  // keep data stable and valid as long as elements are dispatched.
  assign ispr_mai_sw_err.busy_write     = ma_in_valid_q &
                                          |{ispr_mai_in0_s0_wr_i, ispr_mai_in0_s1_wr_i,
                                            ispr_mai_in1_s0_wr_i, ispr_mai_in1_s1_wr_i};
  assign ispr_mai_sw_err.rsvd_csr_write = ispr_mai_ctrl_wr_i & (|ispr_mai_ctrl_w.rsvd);
  // The configuration latched when an execution starts must be valid.
  assign ispr_mai_sw_err.invalid_op     = !(ma_mask_op_d inside
                                          {SecAdd, SecAddMod, ArithToBool, BoolToArith}) & ma_start;

  // Valid control
  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_valid_control_state
    if (!rst_ni) begin
      ma_in_valid_q <= 1'b0;
    end else begin
      if (in_cnt_set) begin
        ma_in_valid_q <= 1'b0;
      end else if (ma_start) begin
        ma_in_valid_q <= 1'b1;
      end
    end
  end

  // Busy control
  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_busy_control_state
    if (!rst_ni) begin
      ma_busy_q <= 1'b0;
    end else begin
      if (out_cnt_set) begin
        ma_busy_q <= 1'b0;
      end else if (ma_start) begin
        ma_busy_q <= 1'b1;
      end
    end
  end

  // Store the operation of the mask accelerator.
  assign ma_mask_op_d = ispr_mai_ctrl_wr_i ? ispr_mai_ctrl_w.op : ma_mask_op_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin : proc_ma_op_store
    if (!rst_ni) begin
      ma_mask_op_q <= SecAdd;
    end else begin
      if (sec_wipe_mai_i) begin
        ma_mask_op_q <= SecAdd;
      end else begin
        ma_mask_op_q <= ma_mask_op_d;
      end
    end
  end


  ////////////////////
  // WSR Bus Access //
  ////////////////////

  // WSR bus write access. Wiping takes priority over writing
  assign ispr_mai_in0_s0_d = sec_wipe_ispr_mai_in0_s0_i ? mai_ispr_urnd.urnd      :
                             ispr_mai_in0_s0_wr_i       ? ispr_mai_in0_s0_wdata_i :
                             ispr_mai_in0_s0_q;

  assign ispr_mai_in0_s1_d = sec_wipe_ispr_mai_in0_s1_i ? mai_ispr_urnd.urnd      :
                             ispr_mai_in0_s1_wr_i       ? ispr_mai_in0_s1_wdata_i :
                             ispr_mai_in0_s1_q;

  assign ispr_mai_in1_s0_d = sec_wipe_ispr_mai_in1_s0_i ? mai_ispr_urnd.urnd      :
                             ispr_mai_in1_s0_wr_i       ? ispr_mai_in1_s0_wdata_i :
                             ispr_mai_in1_s0_q;

  assign ispr_mai_in1_s1_d = sec_wipe_ispr_mai_in1_s1_i ? mai_ispr_urnd.urnd      :
                             ispr_mai_in1_s1_wr_i       ? ispr_mai_in1_s1_wdata_i :
                             ispr_mai_in1_s1_q;

  always_comb begin : proc_res_s0_next
    // Bus access
    ispr_mai_res_s0_d = sec_wipe_ispr_mai_res_s0_i ? mai_ispr_urnd.urnd      :
                        ispr_mai_res_s0_wr_i       ? ispr_mai_res_s0_wdata_i :
                        ispr_mai_res_s0_q;

    // Accelerator access has prio
    for (int i = 0; i < BaseWordsPerWLEN; i++) begin : gen_word_acc_write_res_s0
      if (ispr_mai_out_demux_sel_onehot[i]) ispr_mai_res_s0_d[i] = ispr_mai_res_s0;
    end
  end

  always_comb begin : proc_res_s1_next
    // Bus access
    ispr_mai_res_s1_d = sec_wipe_ispr_mai_res_s1_i ? mai_ispr_urnd.urnd      :
                        ispr_mai_res_s1_wr_i       ? ispr_mai_res_s1_wdata_i :
                        ispr_mai_res_s1_q;

    // Accelerator access has priority
    for (int i = 0; i < BaseWordsPerWLEN; i++) begin : gen_word_acc_write_res_s1
      if (ispr_mai_out_demux_sel_onehot[i]) ispr_mai_res_s1_d[i] = ispr_mai_res_s1;
    end
  end

  // WSR bus read access
  // always present the output of the registers, the ISPR multiplexing logic blanks the signals
  assign ispr_mai_in0_s0_rdata_o = ispr_mai_in0_s0_q;
  assign ispr_mai_in0_s1_rdata_o = ispr_mai_in0_s1_q;
  assign ispr_mai_in1_s0_rdata_o = ispr_mai_in1_s0_q;
  assign ispr_mai_in1_s1_rdata_o = ispr_mai_in1_s1_q;
  assign ispr_mai_res_s0_rdata_o = ispr_mai_res_s0_q;
  assign ispr_mai_res_s1_rdata_o = ispr_mai_res_s1_q;

  // Non-resettable WSR data store. A known value will be set during secure wiping
  always_ff @(posedge clk_i) begin : proc_wsr_data_store
    ispr_mai_in0_s0_q <= ispr_mai_in0_s0_d;
    ispr_mai_in0_s1_q <= ispr_mai_in0_s1_d;
    ispr_mai_in1_s0_q <= ispr_mai_in1_s0_d;
    ispr_mai_in1_s1_q <= ispr_mai_in1_s1_d;
    ispr_mai_res_s0_q <= ispr_mai_res_s0_d;
    ispr_mai_res_s1_q <= ispr_mai_res_s1_d;
  end


  ////////////////////
  // Error Handling //
  ////////////////////

  // Calculate the masked ECC integrity error signal
  always_comb begin : proc_mai_reg_intg_violation_err_masked
    mai_reg_intg_violation_err_masked = 1'b1;
    unique case (ma_mask_op_q)
      // All input words but not the mod least significant word of the mod register
      SecAdd: begin
        mai_reg_intg_violation_err_masked = (|mai_reg_intg_violation_err.in0_s0) |
                                            (|mai_reg_intg_violation_err.in0_s1) |
                                            (|mai_reg_intg_violation_err.in1_s0) |
                                            (|mai_reg_intg_violation_err.in1_s1);
      end
      // All inputs
      SecAddMod: begin
        mai_reg_intg_violation_err_masked = (|mai_reg_intg_violation_err.in0_s0) |
                                            (|mai_reg_intg_violation_err.in0_s1) |
                                            (|mai_reg_intg_violation_err.in1_s0) |
                                            (|mai_reg_intg_violation_err.in1_s1) |
                                            (|mai_reg_intg_violation_err.mod);
      end
      // Input 0 and the least significant word of the mod register
      ArithToBool, BoolToArith: begin
        mai_reg_intg_violation_err_masked = (|mai_reg_intg_violation_err.in0_s0) |
                                            (|mai_reg_intg_violation_err.in0_s1) |
                                            (|mai_reg_intg_violation_err.mod);
      end
      default:;
    endcase
  end

  // An integrity error happens if we access an invalid word
  assign mai_reg_intg_violation_err_o = mai_reg_intg_violation_err_masked & ma_in_consume;
  // State errors
  assign mai_state_err_o              = |mai_state_err;
  // Sw error
  assign mai_software_error_o         = |ispr_mai_sw_err;

  // The masking accelerator requires mod and operation to be stable during an execution. This
  // check is much simpler when we base it on the busy flag instead of recreating the information
  // inside the MA. These must remain stable also during a secure wipe.



endmodule
