    logic close;
    logic done;
    logic proc;
    logic send;
    logic start;
  } kmac_cmd_t;

  typedef struct packed {
    lowrisc_kmac_pkg::app_mode_e        mode;
    lowrisc_sha3_pkg::keccak_strength_e kstrength;
    logic                       en_xof;
  } kmac_cfg_t;

  typedef struct packed {
    logic msg_write_error;
    logic ctrl_error;
    logic rsp_error;
    logic rsp_valid;
    logic ready;
  } kmac_status_t;

