/////////////////////////////////////





/////////////////////
// Register Macros //
/////////////////////

// TODO: define other variations of register macros so that they can be used throughout all designs
// to make the code more concise.

// Register with asynchronous reset.


///////////////////////////
// Macro for Sparse FSMs //
///////////////////////////

// Simulation tools typically infer FSMs and report coverage for these separately. However, tools
// like Xcelium and VCS seem to have problems inferring FSMs if the state register is not coded in
// a behavioral always_ff block in the same hierarchy. To that end, this uses a modified variant
// with a second behavioral register definition for RTL simulations so that FSMs can be inferred.
// Note that in this variant, the __q output is disconnected from prim_sparse_fsm_flop and attached
// to the behavioral flop. An assertion is added to ensure equivalence between the
// prim_sparse_fsm_flop output and the behavioral flop output in that case.


 // PRIM_FLOP_MACROS_SV


 // PRIM_ASSERT_SV


module lowrisc_otbn_reg_top (
  input clk_i,
  input rst_ni,
  input  lowrisc_tlul_pkg::tl_h2d_t tl_i,
  output lowrisc_tlul_pkg::tl_d2h_t tl_o,

  // Output port for window
  output lowrisc_tlul_pkg::tl_h2d_t tl_win_o  [2],
  input  lowrisc_tlul_pkg::tl_d2h_t tl_win_i  [2],

  // To HW
  output lowrisc_otbn_reg_pkg::otbn_reg2hw_t reg2hw, // Write
  input  lowrisc_otbn_reg_pkg::otbn_hw2reg_t hw2reg, // Read

  // Integrity check errors
  output logic intg_err_o
);

  import lowrisc_otbn_reg_pkg::* ;

  localparam int AW = 16;
  localparam int DW = 32;
  localparam int DBW = DW/8;                    // Byte Width

  // register signals
  logic           reg_we;
  logic           reg_re;
  logic [AW-1:0]  reg_addr;
  logic [DW-1:0]  reg_wdata;
  logic [DBW-1:0] reg_be;
  logic [DW-1:0]  reg_rdata;
  logic           reg_error;

  logic          addrmiss, wr_err;

  logic [DW-1:0] reg_rdata_next;
  logic reg_busy;

  lowrisc_tlul_pkg::tl_h2d_t tl_reg_h2d;
  lowrisc_tlul_pkg::tl_d2h_t tl_reg_d2h;


  // incoming payload check
  logic intg_err;
  lowrisc_tlul_cmd_intg_chk u_chk (
    .tl_i(tl_i),
    .err_o(intg_err)
  );

  // also check for spurious write enables
  logic reg_we_err;
  logic [10:0] reg_we_check;
  lowrisc_prim_reg_we_check #(
    .OneHotWidth(11)
  ) u_prim_reg_we_check (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .oh_i  (reg_we_check),
    .en_i  (reg_we && !addrmiss),
    .err_o (reg_we_err)
  );

  logic err_q;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      err_q <= '0;
    end else if (intg_err || reg_we_err) begin
      err_q <= 1'b1;
    end
  end

  // integrity error output is permanent and should be used for alert generation
  // register errors are transactional
  assign intg_err_o = err_q | intg_err | reg_we_err;

  // outgoing integrity generation
  lowrisc_tlul_pkg::tl_d2h_t tl_o_pre;
  lowrisc_tlul_rsp_intg_gen #(
    .EnableRspIntgGen(1),
    .EnableDataIntgGen(0)
  ) u_rsp_intg_gen (
    .tl_i(tl_o_pre),
    .tl_o(tl_o)
  );

  lowrisc_tlul_pkg::tl_h2d_t tl_socket_h2d [3];
  lowrisc_tlul_pkg::tl_d2h_t tl_socket_d2h [3];

  logic [1:0] reg_steer;

  // socket_1n connection
  assign tl_reg_h2d = tl_socket_h2d[2];
  assign tl_socket_d2h[2] = tl_reg_d2h;

  assign tl_win_o[0] = tl_socket_h2d[0];
  assign tl_socket_d2h[0] = tl_win_i[0];
  assign tl_win_o[1] = tl_socket_h2d[1];
  assign tl_socket_d2h[1] = tl_win_i[1];

  // Create Socket_1n
  lowrisc_tlul_socket_1n #(
    .N            (3),
    .HReqPass     (1'b1),
    .HRspPass     (1'b1),
    .DReqPass     ({3{1'b1}}),
    .DRspPass     ({3{1'b1}}),
    .HReqDepth    (4'h0),
    .HRspDepth    (4'h0),
    .DReqDepth    ({3{4'h0}}),
    .DRspDepth    ({3{4'h0}}),
    .ExplicitErrs (1'b0)
  ) u_socket (
    .clk_i  (clk_i),
    .rst_ni (rst_ni),
    .tl_h_i (tl_i),
    .tl_h_o (tl_o_pre),
    .tl_d_o (tl_socket_h2d),
    .tl_d_i (tl_socket_d2h),
    .dev_select_i (reg_steer)
  );

  // Create steering logic
  always_comb begin
    reg_steer =
        tl_i.a_address[AW-1:0] inside {[16384:32767]} ? 2'd0 :
        tl_i.a_address[AW-1:0] inside {[32768:49151]} ? 2'd1 :
        // Default set to register
        2'd2;

    // Override this in case of an integrity error
    if (intg_err) begin
      reg_steer = 2'd2;
    end
  end

  lowrisc_tlul_adapter_reg #(
    .RegAw(AW),
    .RegDw(DW),
    .EnableDataIntgGen(1)
  ) u_reg_if (
    .clk_i  (clk_i),
    .rst_ni (rst_ni),

    .tl_i (tl_reg_h2d),
    .tl_o (tl_reg_d2h),

    .en_ifetch_i(lowrisc_prim_mubi_pkg::MuBi4False),
    .intg_error_o(),

    .we_o    (reg_we),
    .re_o    (reg_re),
    .addr_o  (reg_addr),
    .wdata_o (reg_wdata),
    .be_o    (reg_be),
    .busy_i  (reg_busy),
    .rdata_i (reg_rdata),
    .error_i (reg_error)
  );

  // cdc oversampling signals

  assign reg_rdata = reg_rdata_next ;
  assign reg_error = addrmiss | wr_err | intg_err;

  // Define SW related signals
  // Format: <reg>_<field>_{wd|we|qs}
  //        or <reg>_{wd|we|qs} if field == 1 or 0
  logic intr_state_we;
  logic intr_state_qs;
  logic intr_state_wd;
  logic intr_enable_we;
  logic intr_enable_qs;
  logic intr_enable_wd;
  logic intr_test_we;
  logic intr_test_wd;
  logic alert_test_we;
  logic alert_test_fatal_wd;
  logic alert_test_recov_wd;
  logic cmd_we;
  logic [7:0] cmd_wd;
  logic ctrl_re;
  logic ctrl_we;
  logic ctrl_software_errs_fatal_qs;
  logic ctrl_software_errs_fatal_wd;
  logic ctrl_wfi_enabled_qs;
  logic ctrl_wfi_enabled_wd;
  logic [7:0] status_qs;
  logic err_bits_re;
  logic err_bits_we;
  logic err_bits_bad_data_addr_qs;
  logic err_bits_bad_data_addr_wd;
  logic err_bits_bad_insn_addr_qs;
  logic err_bits_bad_insn_addr_wd;
  logic err_bits_call_stack_qs;
  logic err_bits_call_stack_wd;
  logic err_bits_illegal_insn_qs;
  logic err_bits_illegal_insn_wd;
  logic err_bits_loop_qs;
  logic err_bits_loop_wd;
  logic err_bits_key_invalid_qs;
  logic err_bits_key_invalid_wd;
  logic err_bits_rnd_rep_chk_fail_qs;
  logic err_bits_rnd_rep_chk_fail_wd;
  logic err_bits_rnd_fips_chk_fail_qs;
  logic err_bits_rnd_fips_chk_fail_wd;
  logic err_bits_mai_software_error_qs;
  logic err_bits_mai_software_error_wd;
  logic err_bits_imem_intg_violation_qs;
  logic err_bits_imem_intg_violation_wd;
  logic err_bits_dmem_intg_violation_qs;
  logic err_bits_dmem_intg_violation_wd;
  logic err_bits_reg_intg_violation_qs;
  logic err_bits_reg_intg_violation_wd;
  logic err_bits_bus_intg_violation_qs;
  logic err_bits_bus_intg_violation_wd;
  logic err_bits_bad_internal_state_qs;
  logic err_bits_bad_internal_state_wd;
  logic err_bits_illegal_bus_access_qs;
  logic err_bits_illegal_bus_access_wd;
  logic err_bits_lifecycle_escalation_qs;
  logic err_bits_lifecycle_escalation_wd;
  logic err_bits_fatal_software_qs;
  logic err_bits_fatal_software_wd;
  logic fatal_alert_cause_imem_intg_violation_qs;
  logic fatal_alert_cause_dmem_intg_violation_qs;
  logic fatal_alert_cause_reg_intg_violation_qs;
  logic fatal_alert_cause_bus_intg_violation_qs;
  logic fatal_alert_cause_bad_internal_state_qs;
  logic fatal_alert_cause_illegal_bus_access_qs;
  logic fatal_alert_cause_lifecycle_escalation_qs;
  logic fatal_alert_cause_fatal_software_qs;
  logic insn_cnt_re;
  logic insn_cnt_we;
  logic [31:0] insn_cnt_qs;
  logic [31:0] insn_cnt_wd;
  logic load_checksum_re;
  logic load_checksum_we;
  logic [31:0] load_checksum_qs;
  logic [31:0] load_checksum_wd;

  // Register instances
  // R[intr_state]: V(False)
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessW1C),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_state (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_state_we),
    .wd     (intr_state_wd),

    // from internal hardware
    .de     (hw2reg.intr_state.de),
    .d      (hw2reg.intr_state.d),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_state.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_state_qs)
  );


  // R[intr_enable]: V(False)
  lowrisc_prim_subreg #(
    .DW      (1),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRW),
    .RESVAL  (1'h0),
    .Mubi    (1'b0)
  ) u_intr_enable (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (intr_enable_we),
    .wd     (intr_enable_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.intr_enable.q),
    .ds     (),

    // to register interface (read)
    .qs     (intr_enable_qs)
  );


  // R[intr_test]: V(True)
  logic intr_test_qe;
  logic [0:0] intr_test_flds_we;
  assign intr_test_qe = &intr_test_flds_we;
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_intr_test (
    .re     (1'b0),
    .we     (intr_test_we),
    .wd     (intr_test_wd),
    .d      ('0),
    .qre    (),
    .qe     (intr_test_flds_we[0]),
    .q      (reg2hw.intr_test.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.intr_test.qe = intr_test_qe;


  // R[alert_test]: V(True)
  logic alert_test_qe;
  logic [1:0] alert_test_flds_we;
  assign alert_test_qe = &alert_test_flds_we;
  //   F[fatal]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_alert_test_fatal (
    .re     (1'b0),
    .we     (alert_test_we),
    .wd     (alert_test_fatal_wd),
    .d      ('0),
    .qre    (),
    .qe     (alert_test_flds_we[0]),
    .q      (reg2hw.alert_test.fatal.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.alert_test.fatal.qe = alert_test_qe;

  //   F[recov]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_alert_test_recov (
    .re     (1'b0),
    .we     (alert_test_we),
    .wd     (alert_test_recov_wd),
    .d      ('0),
    .qre    (),
    .qe     (alert_test_flds_we[1]),
    .q      (reg2hw.alert_test.recov.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.alert_test.recov.qe = alert_test_qe;


  // R[cmd]: V(True)
  logic cmd_qe;
  logic [0:0] cmd_flds_we;
  assign cmd_qe = &cmd_flds_we;
  lowrisc_prim_subreg_ext #(
    .DW    (8)
  ) u_cmd (
    .re     (1'b0),
    .we     (cmd_we),
    .wd     (cmd_wd),
    .d      ('0),
    .qre    (),
    .qe     (cmd_flds_we[0]),
    .q      (reg2hw.cmd.q),
    .ds     (),
    .qs     ()
  );
  assign reg2hw.cmd.qe = cmd_qe;


  // R[ctrl]: V(True)
  logic ctrl_qe;
  logic [1:0] ctrl_flds_we;
  assign ctrl_qe = &ctrl_flds_we;
  //   F[software_errs_fatal]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_ctrl_software_errs_fatal (
    .re     (ctrl_re),
    .we     (ctrl_we),
    .wd     (ctrl_software_errs_fatal_wd),
    .d      (hw2reg.ctrl.software_errs_fatal.d),
    .qre    (),
    .qe     (ctrl_flds_we[0]),
    .q      (reg2hw.ctrl.software_errs_fatal.q),
    .ds     (),
    .qs     (ctrl_software_errs_fatal_qs)
  );
  assign reg2hw.ctrl.software_errs_fatal.qe = ctrl_qe;

  //   F[wfi_enabled]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_ctrl_wfi_enabled (
    .re     (ctrl_re),
    .we     (ctrl_we),
    .wd     (ctrl_wfi_enabled_wd),
    .d      (hw2reg.ctrl.wfi_enabled.d),
    .qre    (),
    .qe     (ctrl_flds_we[1]),
    .q      (reg2hw.ctrl.wfi_enabled.q),
    .ds     (),
    .qs     (ctrl_wfi_enabled_qs)
  );
  assign reg2hw.ctrl.wfi_enabled.qe = ctrl_qe;


  // R[status]: V(False)
  lowrisc_prim_subreg #(
    .DW      (8),
    .SwAccess(lowrisc_prim_subreg_pkg::SwAccessRO),
    .RESVAL  (8'h4),
    .Mubi    (1'b0)
  ) u_status (
    .clk_i   (clk_i),
    .rst_ni  (rst_ni),

    // from register interface
    .we     (1'b0),
    .wd     ('0),

    // from internal hardware
    .de     (hw2reg.status.de),
    .d      (hw2reg.status.d),

    // to internal hardware
    .qe     (),
    .q      (),
    .ds     (),

    // to register interface (read)
    .qs     (status_qs)
  );


  // R[err_bits]: V(True)
  logic err_bits_qe;
  logic [16:0] err_bits_flds_we;
  assign err_bits_qe = &err_bits_flds_we;
  //   F[bad_data_addr]: 0:0
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_err_bits_bad_data_addr (
    .re     (err_bits_re),
    .we     (err_bits_we),
    .wd     (err_bits_bad_data_addr_wd),
    .d      (hw2reg.err_bits.bad_data_addr.d),
    .qre    (),
    .qe     (err_bits_flds_we[0]),
    .q      (reg2hw.err_bits.bad_data_addr.q),
    .ds     (),
    .qs     (err_bits_bad_data_addr_qs)
  );
  assign reg2hw.err_bits.bad_data_addr.qe = err_bits_qe;

  //   F[bad_insn_addr]: 1:1
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_err_bits_bad_insn_addr (
    .re     (err_bits_re),
    .we     (err_bits_we),
    .wd     (err_bits_bad_insn_addr_wd),
    .d      (hw2reg.err_bits.bad_insn_addr.d),
    .qre    (),
    .qe     (err_bits_flds_we[1]),
    .q      (reg2hw.err_bits.bad_insn_addr.q),
    .ds     (),
    .qs     (err_bits_bad_insn_addr_qs)
  );
  assign reg2hw.err_bits.bad_insn_addr.qe = err_bits_qe;

  //   F[call_stack]: 2:2
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_err_bits_call_stack (
    .re     (err_bits_re),
    .we     (err_bits_we),
    .wd     (err_bits_call_stack_wd),
    .d      (hw2reg.err_bits.call_stack.d),
    .qre    (),
    .qe     (err_bits_flds_we[2]),
    .q      (reg2hw.err_bits.call_stack.q),
    .ds     (),
    .qs     (err_bits_call_stack_qs)
  );
  assign reg2hw.err_bits.call_stack.qe = err_bits_qe;

  //   F[illegal_insn]: 3:3
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_err_bits_illegal_insn (
    .re     (err_bits_re),
    .we     (err_bits_we),
    .wd     (err_bits_illegal_insn_wd),
    .d      (hw2reg.err_bits.illegal_insn.d),
    .qre    (),
    .qe     (err_bits_flds_we[3]),
    .q      (reg2hw.err_bits.illegal_insn.q),
    .ds     (),
    .qs     (err_bits_illegal_insn_qs)
  );
  assign reg2hw.err_bits.illegal_insn.qe = err_bits_qe;

  //   F[loop]: 4:4
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_err_bits_loop (
    .re     (err_bits_re),
    .we     (err_bits_we),
    .wd     (err_bits_loop_wd),
    .d      (hw2reg.err_bits.loop.d),
    .qre    (),
    .qe     (err_bits_flds_we[4]),
    .q      (reg2hw.err_bits.loop.q),
    .ds     (),
    .qs     (err_bits_loop_qs)
  );
  assign reg2hw.err_bits.loop.qe = err_bits_qe;

  //   F[key_invalid]: 5:5
  lowrisc_prim_subreg_ext #(
    .DW    (1)
  ) u_err_bits_key_invalid (
    .re     (err_bits_re),
    .we     (err_bits_we),
    .wd     (err_bits_key_invalid_wd),
    .d      (hw2reg.err_bits.key_invalid.d),
    .qre    (),
    .qe     (err_bits_flds_we[5]),
    .q      (reg2hw.err_bits.key_invalid.q),
    .ds     (),
