///////////////////////////
// Macro for Sparse FSMs //
///////////////////////////

// Simulation tools typically infer FSMs and report coverage for these separately. However, tools
// like Xcelium and VCS seem to have problems inferring FSMs if the state register is not coded in
// a behavioral always_ff block in the same hierarchy. To that end, this uses a modified variant
// with a second behavioral register definition for RTL simulations so that FSMs can be inferred.
// Note that in this variant, the __q output is disconnected from prim_sparse_fsm_flop and attached
// to the behavioral flop. An assertion is added to ensure equivalence between the
// prim_sparse_fsm_flop output and the behavioral flop output in that case.


 // PRIM_FLOP_MACROS_SV


 // PRIM_ASSERT_SV


module lowrisc_keymgr_dpe_op_state_ctrl
  import lowrisc_keymgr_dpe_pkg::*;
  import lowrisc_keymgr_dpe_reg_pkg::*;
(
  input clk_i,
  input rst_ni,

  input adv_req_i,
  input gen_req_i,
  input erase_req_i,
  input dis_req_i,
  input load_req_i,

  // `op_ack_o` signals to the top module that the requested operation is completed
  output logic op_ack_o,
  output logic op_busy_o,
  // `op_update_o` signals to the keygmr slot MUX that destination slot needs to be updated
  output logic op_update_o,

  input kmac_done_i,
  output logic adv_en_o,
  output logic gen_en_o,

  output logic op_fsm_err_o

);

  // Encoding generated with:
  // $ ./util/design/sparse-fsm-encode.py -d 5 -m 4 -n 8 \
  //     -s 1155716906 --language=sv
  //
  // Hamming distance histogram:
  //
  //  0: --
  //  1: --
  //  2: --
  //  3: --
  //  4: --
  //  5: |||||||||||||||||||| (66.67%)
  //  6: |||||||||| (33.33%)
  //  7: --
  //  8: --
  //
  // Minimum Hamming distance: 5
  // Maximum Hamming distance: 6
  // Minimum Hamming weight: 2
  // Maximum Hamming weight: 6
  //
  localparam int StateWidth = 8;
  typedef enum logic [StateWidth-1:0] {
    StIdle = 8'b11101110,
    StAdv = 8'b00000101,
    StWait = 8'b01110011,
    StSingleCycle = 8'b10011000
  } state_e;

  state_e state_q, state_d;


    lowrisc_prim_sparse_fsm_flop #(
      .StateEnumT(state_e),
      .Width($bits(state_e)),
      .ResetValue($bits(state_e)'(StIdle)),
      .EnableAlertTriggerSVA(1)
    ) u_state_regs (
      .clk_i   ( clk_i   ),
      .rst_ni  ( rst_ni ),
      .state_i ( state_d     ),
      .state_o ( state_q     )
    );


  logic gen_en;
  assign gen_en_o = gen_en & gen_req_i;

  always_comb begin
    state_d = state_q;
    op_update_o = 1'b0;
    op_ack_o = 1'b0;
    op_busy_o = 1'b0;

    // output to kmac interface
    adv_en_o = 1'b0;

    gen_en = 1'b0;
    op_fsm_err_o = 1'b0;

    unique case (state_q)
      StIdle: begin
        if (dis_req_i) begin
          state_d = StSingleCycle;
        end else if (adv_req_i) begin
          state_d = StAdv;
        end else if (gen_req_i) begin
          state_d = StWait;
        end else if (erase_req_i) begin
          state_d = StSingleCycle;
        end else if (load_req_i) begin
          state_d = StSingleCycle;
        end
      end

      // Erasing, disabling, and loading root key happen in a single clock cycle in keymgr slot
      // MUX of ctrl, therefore:
      // `op_update_o` signal is used as input to MUX (so that MUX is activated to update the slot)
      // `op_ack_o` signal is used to communicate successful completion of command
      StSingleCycle: begin
        op_ack_o = 1'b1;
        op_update_o = 1'b1;
        state_d = StIdle;
      end

      StAdv: begin
        adv_en_o = 1'b1;
        op_busy_o = 1'b1;

        if (kmac_done_i) begin
          op_ack_o = 1'b1;
          op_update_o = 1'b1;
          state_d = StIdle;
        end
      end

      // Not an advanced operation
      StWait: begin
        gen_en = 1'b1;
        op_busy_o = 1'b1;

        if (kmac_done_i) begin
          op_ack_o = 1'b1;
          state_d = StIdle;
        end
      end

      // error state
      default: begin
        // allow completion of transaction
        op_ack_o = 1'b1;
        op_fsm_err_o = 1'b1;
        op_busy_o = 1'b1;
      end

    endcase // unique case (adv_state_q)
  end


endmodule // keymgr_dpe_op_state_ctrl
