  assign unused_rst_en[2] = rstmgr_rst_en.lc_aon_shadowed[lowrisc_rstmgr_pkg::DomainMainSel];
  assign unused_rst_en[3] = rstmgr_rst_en.lc_main[lowrisc_rstmgr_pkg::DomainAonSel];
  assign unused_rst_en[4] = rstmgr_rst_en.lc_main_shadowed[lowrisc_rstmgr_pkg::DomainAonSel];
  assign unused_rst_en[5] = rstmgr_rst_en.lc_main_shadowed[lowrisc_rstmgr_pkg::DomainMainSel];
